def _space_cutoff(now: Optional[datetime] = None, **delta) -> str:
    """
    B-07: cutoff دقیقاً هم‌فرمت مقدار ذخیره‌شده در ستون created_at
    (که با datetime('now', 'localtime') → 'YYYY-MM-DD HH:MM:SS' ساخته می‌شود)
    تا مقایسهٔ رشته‌ای درست باشد و index زنده بماند.
    """
    now = now or datetime.now()
    return (now - timedelta(**delta)).strftime("%Y-%m-%d %H:%M:%S")

def stable_trade_hash(trade_id: str) -> int:
    """
    B-12: hash پایدار بین‌ری‌استارت (برخلاف hash() که به PYTHONHASHSEED وابسته است).
    """
    return int.from_bytes(
        hashlib.md5(str(trade_id).encode("utf-8")).digest()[:8], "big"
    )

def safe_cache_path(base_dir: Path, key: str, subdir: int = 2) -> Path:
    """
    B-10: کلیدهایی مثل 'EUR/USD' دیگر نمی‌توانند مسیر را بشکنند.
    """
    sanitized = (
        str(key)
        .replace("/", "__")
        .replace(os.sep, "__")
        .replace("..", "__")
    )
    prefix = sanitized[:subdir] if len(sanitized) >= subdir else sanitized
    return Path(base_dir) / prefix / f"{sanitized}.cache"

def _resolve_penalty_dir(base_dir: Optional[str] = None) -> str:
    """
    زیرشاخهٔ penalty را برمی‌گرداند و در صورت نیاز می‌سازد:
        <root>/TRADE/STRATEGIES/penalty

    self-heal: اگر base_dir خودش داخل TRADE باشد یا به TRADE ختم شود،
    به والد آن منتقل می‌شویم تا از «TRADE/TRADE» جلوگیری شود.
    """
    root = Path(base_dir or os.getcwd()).resolve()

    # ── جلوگیری از تکرار TRADE ──────────────────────────────
    if root.name.upper() == "TRADE":
        root = root.parent
    elif root.name.upper() == "STRATEGIES" and root.parent.name.upper() == "TRADE":
        root = root.parent.parent

    penalty_dir = root / "TRADE" / "STRATEGIES" / "penalty"
    try:
        penalty_dir.mkdir(parents=True, exist_ok=True)
    except OSError as e:
        logger.warning(
            f"[PenaltyManager] ⚠️ Could not create penalty dir {penalty_dir}: {e}"
        )
    return str(penalty_dir)

def garman_klass_vol(
    high: np.ndarray,
    low: np.ndarray,
    close: np.ndarray,
    open_: np.ndarray,
) -> float:
    """
    B-11: GK با clip در صفر (برآورد GK در هر bar لزوماً مثبت نیست؛
    منبع NaN ریشه‌کن می‌شود به‌جای اینکه warning suppress شود).
    """
    hl = (high - low) ** 2
    co = (close - open_) ** 2
    gk_bar = 0.5 * hl - (2.0 * math.log(2.0) - 1.0) * co
    gk_bar = np.clip(gk_bar, 0.0, None)  # B-11
    if gk_bar.size == 0:
        return 0.0
    return float(np.sqrt(gk_bar.mean()))

def determine_decision(final_score: float, context: Dict,
                       orchestrator_decision: str,
                       orchestrator_confidence: float) -> Tuple[Decision, float, str]:
    """نسخهٔ اصلاح‌شدهٔ کامل _determine_decision (B-06).
    CLOSE فقط وقتی سیگنال در جهت «مخالف» پوزیشن باز باشد."""
    phase = "MDE_DETERMINE_DECISION_V4"
    try:
        logger.info(f"[{phase}] Determining final decision...")
        confidence = max(orchestrator_confidence, abs(final_score))
        portfolio = context.get("portfolio_risk", {})
        if isinstance(portfolio, dict) and not portfolio.get("is_trading_allowed", True):
            return Decision.HOLD, 0.5, "Portfolio risk limit exceeded"
        has_position = context.get("has_position", False)
        position_type = context.get("position_type", None)
        position_pnl = context.get("position_pnl", 0.0)
        if has_position:
            # B-06: سیگنال SELL => بستن LONG (نه SHORT)
            if orchestrator_decision in ["STRONG_SELL", "SELL"] and final_score <= -0.5:
                if position_type == "BUY":
                    return Decision.CLOSE_LONG, confidence, "Orchestrator sell signal, closing long"
            # B-06: سیگنال BUY => بستن SHORT (نه LONG)
            if orchestrator_decision in ["STRONG_BUY", "BUY"] and final_score >= 0.5:
                if position_type == "SELL":
                    return Decision.CLOSE_SHORT, confidence, "Orchestrator buy signal, closing short"
            if position_pnl < -0.05:
                if position_type == "BUY":
                    return Decision.CLOSE_LONG, 0.7, "Stop loss triggered"
                elif position_type == "SELL":
                    return Decision.CLOSE_SHORT, 0.7, "Stop loss triggered"
            if position_pnl > 0.08:
                if position_type == "BUY":
                    return Decision.CLOSE_LONG, 0.7, "Take profit triggered"
                elif position_type == "SELL":
                    return Decision.CLOSE_SHORT, 0.7, "Take profit triggered"
            if abs(final_score) < 0.3 and orchestrator_confidence < 0.55:
                return Decision.HOLD, 0.5, "Weak signal, holding position"
        max_positions = context.get("max_positions", 100)
        current_positions = context.get("current_positions", 0)
        if current_positions >= max_positions:
            return Decision.HOLD, 0.5, "Position limit reached"
        if orchestrator_decision in ["STRONG_BUY", "STRONG_SELL"] and orchestrator_confidence >= 0.70:
            decision = Decision.STRONG_BUY if "BUY" in orchestrator_decision else Decision.STRONG_SELL
            return decision, orchestrator_confidence, f"Orchestrator strong signal: {orchestrator_decision}"
        if orchestrator_decision in ["BUY", "SELL"] and orchestrator_confidence >= 0.60:
            decision = Decision.BUY if "BUY" in orchestrator_decision else Decision.SELL
            return decision, orchestrator_confidence, f"Orchestrator signal: {orchestrator_decision}"
        if final_score >= 0.7:
            return Decision.STRONG_BUY, confidence, "Strong buy signal from score"
        elif final_score <= -0.7:
            return Decision.STRONG_SELL, confidence, "Strong sell signal from score"
        elif final_score >= 0.4:
            return Decision.BUY, confidence, "Buy signal from score"
        elif final_score <= -0.4:
            return Decision.SELL, confidence, "Sell signal from score"
        return Decision.HOLD, 0.5, "No strong signal"
    except Exception as e:
        logger.error(f"[{phase}] Decision determination error: {e}", exc_info=True)
        return Decision.HOLD, 0.5, f"Error: {str(e)}"

def calculate_fallback_size(current_price: float, stop_loss: float,
                            context: dict, max_risk_per_trade: float = 0.02) -> float:
    """نسخهٔ اصلاح‌شده (B-08): ارجاع به `phase` (نامتعریف) حذف شد تا
    NameError دیگر در debug-log نخورد و مقدار واقعی برنگردد."""
    try:
        balance = float(context.get("account_balance", 10000))
        risk_pct = float(max_risk_per_trade)
        risk_amount = balance * risk_pct
        stop_distance = abs(float(current_price) - float(stop_loss))
        if stop_distance > 0:
            size = risk_amount / stop_distance
        else:
            size = (balance * 0.02) / (float(current_price) * 0.01)
        logger.debug("AEI fallback size — Balance: $%.2f, Risk: %.2f%%, Size: %.2f",
                     balance, risk_pct * 100, size)
        return max(0.01, min(10.0, size))
    except Exception as e:
        logger.error("AEI fallback size failed: %s", e, exc_info=True)
        return 0.01

async def bootstrap_unified_schema(
    db_path: Optional[Path] = None,
    drop_legacy_table: bool = False,
) -> Dict[str, int]:
    """این تابع فقط `migrate_to_unified_schema` را صدا می‌زند — بدون schema خودش."""
    if db_path is None:
        db_path = Path("TRADE/strategy_stats.db")
    return await migrate_to_unified_schema(
        db_path=Path(db_path),
        drop_legacy_table=drop_legacy_table,
    )
    
def _infer_hold_quality_from_reason(
    reason: str,
    is_fallback: bool = False,
    error_type: str = "None",
) -> float:
    """
    ✅ استنتاج hold_quality از متن reason وقتی مقدار صریح وجود ندارد.

    نگاشت‌ها:
      - خطای واقعی + insufficient data → 0.55 (مشکل دسترسی به داده، نه باگ)
      - خطای واقعی (باگ)              → 0.30
      - No setup / gate rejected       → 0.78
      - Regime-suppressed hold         → 0.82
      - Insufficient بدون خطا          → 0.60
      - Default analytical hold        → 0.70

    Returns:
        float: hold_quality ∈ [0.30, 0.90]
    """
    try:
        r = str(reason or "").lower()
        et = str(error_type or "None").lower()

        # ─── Real error path ────────────────────────────────────────────
        if is_fallback or et not in ("none", "", "null"):
            if any(k in r for k in (
                "insufficient data", "insufficient history",
                "insufficient bars", "not enough data",
                "too few bars", "validation failed",
                "missing columns", "too much nan",
            )):
                return 0.55
            return 0.30

        # ─── No reason at all ──────────────────────────────────────────
        if not r or r in ("n/a", "none", "unknown"):
            return 0.60

        # ─── "No setup" style reasons ──────────────────────────────────
        if any(k in r for k in (
            "no clear", "no setup", "no qualified", "no high-quality",
            "no valid", "no dominant", "no aligned",
            "insufficient confluence", "below", "gate rejected",
            "insufficient agreement", "weak agreement",
            "conflict", "conflicting",
        )):
            return 0.78

        # ─── Regime-suppressed reasons ─────────────────────────────────
        if any(k in r for k in (
            "ranging", "suppressed", "regime", "range bound",
            "sideways", "quiet", "low volatility", "dead",
        )):
            return 0.82

        # ─── Insufficient data without is_fallback flag ────────────────
        if any(k in r for k in (
            "insufficient", "not enough", "too few",
            "short history", "warm-up", "cold start",
        )):
            return 0.60

        # ─── Default analytical hold ───────────────────────────────────
        return 0.70
    except Exception:
        return 0.60
        
async def migrate_to_unified_schema(
    db_path: Path,
    drop_legacy_table: bool = False,
) -> Dict[str, int]:
    """
    Migration یک‌باره — فقط داده‌های legacy را به signals منتقل می‌کند.

    ✅ FIXED V2:
        • از سینگلتون get_global_stats_manager استفاده می‌کند (نه ساخت نمونه).
        • clear_cache روی همان singleton فراخوانی می‌شود
          (نه self.clear_cache که NameError بود).
        • Lazy-resolve برای جلوگیری از NameError در صورت import زودهنگام.
    """
    phase = "MIGRATE_UNIFIED_SCHEMA_V2"
    stats = {
        "signals_created": 0,
        "signals_migrated": 0,
        "outcomes_table_created": 0,
        "legacy_table_dropped": 0,
    }

    db_path = Path(db_path)
    db_path.parent.mkdir(parents=True, exist_ok=True)

    # ✅ Lazy-resolve singleton (مقاوم در برابر ترتیب import)
    gm_factory = globals().get("get_global_stats_manager")
    try:
        if gm_factory is not None:
            gm = gm_factory(db_path=str(db_path))
        else:
            gm = GlobalStrategyStatsManager(db_path=str(db_path))
    except Exception as e:
        logger.error(f"[{phase}] Schema init failed: {e}")
        return stats

    stats["signals_created"] = 1
    stats["outcomes_table_created"] = 1

    def _run() -> Dict[str, int]:
        with sqlite3.connect(str(db_path), timeout=15.0) as conn:
            cur = conn.cursor()

            cur.execute(
                "SELECT name FROM sqlite_master "
                "WHERE type='table' AND name='strategy_signals'"
            )
            if cur.fetchone() is None:
                return stats

            system_start = datetime.now().isoformat()
            cur.execute("""
                SELECT symbol, strategy_name, signal, confidence, score,
                       COALESCE(hold_quality, NULL), timestamp
                FROM strategy_signals
                WHERE symbol IS NOT NULL AND strategy_name IS NOT NULL
            """)
            for row in cur.fetchall():
                try:
                    cur.execute("""
                        INSERT OR IGNORE INTO signals
                        (symbol, strategy_name, signal, confidence,
                         score, reason, is_fallback, error_type,
                         is_poisoned, hold_quality, timestamp,
                         system_start_time)
                        VALUES (?, ?, ?, ?, ?, ?, 0, 'None', 0, ?, ?, ?)
                    """, (
                        row[0], row[1], row[2], float(row[3] or 0.0),
                        float(row[4] or 50.0), "migrated_from_legacy",
                        row[5], row[6], system_start,
                    ))
                    if cur.rowcount > 0:
                        stats["signals_migrated"] += 1
                except (sqlite3.Error, ValueError, TypeError):
                    continue

            if drop_legacy_table:
                cur.execute("DROP TABLE strategy_signals")
                stats["legacy_table_dropped"] = 1

            conn.commit()

        # ✅ FIXED: on singleton — نه self (که NameError می‌داد)
        try:
            gm.clear_cache()
        except Exception:
            pass

        return stats

    try:
        stats = await asyncio.to_thread(_run)
        logger.info(f"[{phase}] ✅ Migration complete: {stats}")
    except Exception as e:
        logger.error(f"[{phase}] ❌ Migration failed: {e}", exc_info=True)

    return stats
    
_SHARED_SFM: Optional['SignalFileManager'] = None
_SHARED_SFM_LOCK = threading.Lock()


def _get_shared_signal_file_manager() -> 'SignalFileManager':
    """
    نمونهٔ singleton از SignalFileManager را برمی‌گرداند.

    در اولین فراخوانی، SFM را می‌سازد و به‌عنوان singleton نگه می‌دارد.
    سایر مصرف‌کنندگان (StrategyScoreBooster، ContinuousLearningEngine، ...)
    باید از این تابع استفاده کنند تا state (از جمله PenaltyManager)
    به‌اشتراک گذاشته شود.
    """
    global _SHARED_SFM
    if _SHARED_SFM is not None:
        return _SHARED_SFM
    with _SHARED_SFM_LOCK:
        if _SHARED_SFM is None:
            _SHARED_SFM = SignalFileManager()
    return _SHARED_SFM


def _set_shared_signal_file_manager(sfm: 'SignalFileManager') -> None:
    """
    ثبت نمونهٔ SFM موجود به‌عنوان singleton سراسری.
    باید پس از `set_penalty_manager` صدا زده شود تا PM در دسترس همه باشد.
    """
    global _SHARED_SFM
    with _SHARED_SFM_LOCK:
        _SHARED_SFM = sfm

# ═══════════════════════════════════════════════════════════════════════
# GLOBAL SIGNAL DEDUPLICATION — cross-instance safety net
# (این بلوک را یک بار، قبل از تعریف کلاس‌ها اضافه کنید)
# ═══════════════════════════════════════════════════════════════════════
_GLOBAL_SIGNAL_DEDUP: Dict[str, float] = {}
_GLOBAL_SIGNAL_DEDUP_LOCK = threading.Lock()
_GLOBAL_SIGNAL_DEDUP_TTL_SECONDS = 120.0


def _global_signal_dedup_check(key: str) -> bool:
    """
    بررسی تکراری‌بودن سراسری (cross-instance) برای ثبت سیگنال.

    این مکانیزم از نوشتن دوگانه جلوگیری می‌کند هنگامی که:
      • SFM.register_signal_full هم‌زمان با
        AdvancedStrategyReportGenerator._record_all_signals_to_database
        برای یک سیگنال صدا زده می‌شوند.
      • کلاس‌ها در threadهای مختلف یا نمونه‌های مختلف ساخته می‌شوند.

    Returns:
        True  → این سیگنال «جدید» است (باید پردازش شود)
        False → این سیگنال در پنجرهٔ TTL اخیر دیده شده (duplicate)
    """
    now = time.time()
    with _GLOBAL_SIGNAL_DEDUP_LOCK:
        # پاکسازی منقضی‌ها
        expired = [
            k for k, v in _GLOBAL_SIGNAL_DEDUP.items()
            if now - v > _GLOBAL_SIGNAL_DEDUP_TTL_SECONDS
        ]
        for k in expired:
            _GLOBAL_SIGNAL_DEDUP.pop(k, None)

        # جلوگیری از رشد نامحدود
        if len(_GLOBAL_SIGNAL_DEDUP) > 5000:
            sorted_items = sorted(
                _GLOBAL_SIGNAL_DEDUP.items(), key=lambda x: x[1]
            )
            for k, _ts in sorted_items[:2500]:
                _GLOBAL_SIGNAL_DEDUP.pop(k, None)

        if key in _GLOBAL_SIGNAL_DEDUP:
            return False
        _GLOBAL_SIGNAL_DEDUP[key] = now
        return True     
