@dataclass
class SignalResult:
    """
    Canonical strategy output. Now self-describing: every consumer can call
    .to_dict() / dict(**) / dataclasses.asdict() and get JSON-safe values.
    """
    symbol: str = ""
    timeframe: str = ""
    direction: str = "HOLD"
    confidence: float = 0.0
    entry_price: Optional[float] = None
    stop_loss: Optional[float] = None
    take_profit: Optional[float] = None
    score: float = 0.0
    strategy: str = ""
    reason: str = ""
    status: str = "OK"
    meta: Dict[str, Any] = field(default_factory=dict)
    created_at: str = field(default_factory=lambda: datetime.now(timezone.utc).isoformat())

    @staticmethod
    def _jsonable(value: Any, depth: int = 0) -> Any:
        """Recursively convert a value to JSON-safe primitives."""
        if depth > 6:
            return repr(value)
        if value is None or isinstance(value, (bool, int, str)):
            return value
        if isinstance(value, float):
            return value if math.isfinite(value) else None
        if isinstance(value, datetime):
            return value.isoformat()
        if isinstance(value, np.generic):
            return SignalResult._jsonable(value.item(), depth + 1)
        if isinstance(value, np.ndarray):
            return [SignalResult._jsonable(v, depth + 1) for v in value.tolist()]
        if isinstance(value, pd.Timestamp):
            return None if pd.isna(value) else value.isoformat()
        if isinstance(value, dict):
            return {str(k): SignalResult._jsonable(v, depth + 1) for k, v in value.items()}
        if isinstance(value, (list, tuple, set, frozenset)):
            return [SignalResult._jsonable(v, depth + 1) for v in value]
        if is_dataclass(value) and not isinstance(value, type):
            return SignalResult._jsonable(asdict(value), depth + 1)
        return repr(value)

    def to_dict(self) -> Dict[str, Any]:
        """Return a plain, JSON-serializable dict of all fields."""
        return {f.name: SignalResult._jsonable(getattr(self, f.name, None))
                for f in fields(self)}

    def keys(self):
        """Enable dict(signal_result) and **unpacking."""
        return [f.name for f in fields(self)]

    def __getitem__(self, key: str) -> Any:
        if key not in {f.name for f in fields(self)}:
            raise KeyError(key)
        return getattr(self, key)

    def get(self, key: str, default: Any = None) -> Any:
        return getattr(self, key, default) if isinstance(key, str) else default

    def is_actionable(self) -> bool:
        """True only for a real BUY/SELL with positive confidence."""
        return (str(self.direction).upper() in ("BUY", "SELL")
                and isinstance(self.confidence, (int, float))
                and math.isfinite(float(self.confidence))
                and float(self.confidence) > 0.0
                and str(self.status).upper() == "OK")

    @classmethod
    def empty(cls, symbol: str = "", timeframe: str = "",
              strategy: str = "", reason: str = "no signal") -> "SignalResult":
        return cls(symbol=str(symbol or ""), timeframe=str(timeframe or ""),
                   direction="HOLD", confidence=0.0, strategy=str(strategy or ""),
                   reason=str(reason), status="EMPTY")

