class AdaptiveExecutionIntelligence:
    """
    +------------------------------------------------------------------------------+
    ¦     ADAPTIVE EXECUTION INTELLIGENCE (AEI) - WALL STREET QUANT EDITION V4.0  ¦
    ¦                      ? FULLY INTEGRATED WITH MDE/PIE/DNA                   ¦
    ¦                      ? SUPPORTS CLOSE/REDUCE DECISIONS                     ¦
    ¦                      ? DYNAMIC POSITION SIZING                             ¦
    ¦                      ? COMPLETE PHASE LOGGING                             ¦
    +------------------------------------------------------------------------------+
    """
    def __init__(self, config: Dict[str, Any] = None):
        self.config = config or {}
        self._min_risk_reward_ratio = self.config.get('min_rr_ratio', 1.5)
        self._max_risk_per_trade = self.config.get('max_risk_pct', 0.02)
        self._order_router = None
        self._portfolio_intelligence = None
        self._engine = None  # Reference to UnifiedTradingEngine
        logger.info("? AdaptiveExecutionIntelligence V4.0 initialized")

    def set_order_router(self, order_router):
        """????? ??????? ???????"""
        self._order_router = order_router

    def set_portfolio_intelligence(self, pie: 'PortfolioIntelligenceEngine'):
        """????? Portfolio Intelligence Engine"""
        self._portfolio_intelligence = pie

    def set_engine(self, engine):
        """????? ???? ?? ????? ???? ???? ?????? ?? ????? ????????"""
        self._engine = engine

   
    async def generate_execution_plan(
        self,
        symbol: str,
        decision: 'Decision',
        current_price: float,
        market_context: Dict[str, Any]
    ) -> Optional['ExecutionPlan']:
        """
        ? FIXED V7: Integrated with PortfolioIntelligenceEngine
        ? FULL PHASE LOGGING
        """
        phase = "AEI_GENERATE_PLAN_V7"
        start_time = time.time()
        
        try:
            logger.info(f"[{phase}] ---------------------------------------------------------------")
            logger.info(f"[{phase}] ?? ENTRY: generate_execution_plan for {symbol}")
            logger.info(f"[{phase}]    Decision: {decision.value if hasattr(decision, 'value') else decision}")
            logger.info(f"[{phase}]    Current Price: {current_price:.5f}")
            
            if decision not in [Decision.BUY, Decision.SELL, Decision.STRONG_BUY, Decision.STRONG_SELL]:
                logger.info(f"[{phase}] ?? Not a trade decision: {decision}")
                return None

            signal_direction = "BUY" if decision in [Decision.BUY, Decision.STRONG_BUY] else "SELL"
            confidence = market_context.get('confidence', 0.5)
            
            # ========== PHASE 1: GET POSITION SIZE AND SL/TP ==========
            try:
                logger.info(f"[{phase}] ?? [1/5] Calculating position size and levels...")
                
                if self._engine and hasattr(self._engine, '_calculate_position_size_and_levels'):
                    lot_size, stop_loss, take_profit = await self._engine._calculate_position_size_and_levels(
                        symbol=symbol,
                        confidence=confidence,
                        current_price=current_price,
                        signal_direction=signal_direction
                    )
                    logger.info(f"[{phase}] ? Calculated using engine method")
                else:
                    # Fallback: ?????? ????
                    atr = market_context.get('atr', current_price * 0.01)
                    sl_multiplier = 1.2 if decision in [Decision.STRONG_BUY, Decision.STRONG_SELL] else 1.8
                    tp_multiplier = 2.5 if decision in [Decision.STRONG_BUY, Decision.STRONG_SELL] else 1.8
                    
                    sl_distance = atr * sl_multiplier
                    tp_distance = atr * tp_multiplier
                    lot_size = self._calculate_fallback_size(current_price, current_price - sl_distance, market_context)
                    
                    if signal_direction == "BUY":
                        stop_loss = current_price - sl_distance
                        take_profit = current_price + tp_distance
                    else:
                        stop_loss = current_price + sl_distance
                        take_profit = current_price - tp_distance
                    
                    logger.info(f"[{phase}] ? Calculated using fallback method)")
                    
            except Exception as calc_err:
                logger.error(f"[{phase}] ? Position calculation error: {calc_err}", exc_info=True)
                return None

            # ========== PHASE 2: VALIDATE R:R ==========
            logger.info(f"[{phase}] ?? [2/5] Validating Risk/Reward...")
            
            risk = abs(current_price - stop_loss)
            reward = abs(take_profit - current_price)
            rr_ratio = reward / risk if risk > 0 else 0
            
            if rr_ratio < self._min_risk_reward_ratio:
                logger.warning(f"[{phase}] ? R:R {rr_ratio:.2f} < {self._min_risk_reward_ratio} - CANCELLING TRADE")
                return None
                
            logger.info(f"[{phase}] ? R:R = {rr_ratio:.2f}")

            # ========== PHASE 3: CHECK PORTFOLIO RISK (INTEGRATED WITH PIE) ==========
            logger.info(f"[{phase}] ?? [3/5] Checking portfolio risk via PIE...")
            
            pie = self._portfolio_intelligence
            risk_manager = getattr(self._engine, 'risk_manager', None)
            
            if pie is not None:
                try:
                    # محاسبه ریسک تخمینی
                    estimated_risk = abs(current_price - stop_loss) * lot_size
                    
                    # بررسی از طریق PIE
                    is_allowed, reason, multiplier = await pie.assess_new_trade(
                        symbol=symbol,
                        direction=signal_direction,
                        estimated_risk=estimated_risk,
                        market_context=market_context
                    )
                    
                    if not is_allowed:
                        logger.warning(f"[{phase}] ? PIE check failed: {reason}")
                        return None
                    
                    # اعمال ضریب کاهشی
                    if multiplier < 1.0:
                        lot_size = lot_size * multiplier
                        logger.info(f"[{phase}] 📊 Position size reduced by multiplier: {multiplier:.2f}")
                        
                except Exception as pie_err:
                    logger.warning(f"[{phase}] ?? PIE error: {pie_err}")
            elif risk_manager is not None:
                # Fallback: استفاده از Risk Manager
                try:
                    if hasattr(risk_manager, 'can_trade'):
                        can_trade, reason = await risk_manager.can_trade(symbol, lot_size, current_price)
                        if not can_trade:
                            logger.warning(f"[{phase}] ? Risk manager check failed: {reason}")
                            return None
                except Exception as rm_err:
                    logger.warning(f"[{phase}] ?? Risk manager error: {rm_err}")
            else:
                logger.info(f"[{phase}] ℹ️ No portfolio check available")

            # ========== PHASE 4: BUILD EXECUTION PLAN ==========
            logger.info(f"[{phase}] ?? [4/5] Building execution plan...")
            
            is_strong = decision in [Decision.STRONG_BUY, Decision.STRONG_SELL]
            is_demo = market_context.get('is_demo', True)
            
            plan = ExecutionPlan(
                entry_price=current_price,
                stop_loss=round(stop_loss, 5),
                take_profit=round(take_profit, 5),
                position_size=lot_size,
                risk_percent=0.01,
                trailing_stop_pct=0.015 if is_strong else None,
                profit_lock_pct=0.01 if is_strong else None,
                execution_algorithm="SNAPSHOT" if is_strong or is_demo else "TWAP"
            )

            elapsed = (time.time() - start_time) * 1000
            logger.info(f"[{phase}] ? Plan generated in {elapsed:.1f}ms")
            logger.info(f"[{phase}]    Size: {lot_size:.2f}")
            logger.info(f"[{phase}]    SL: {stop_loss:.5f}")
            logger.info(f"[{phase}]    TP: {take_profit:.5f}")
            logger.info(f"[{phase}]    RR: {rr_ratio:.2f}")
            logger.info(f"[{phase}] ---------------------------------------------------------------")

            return plan

        except Exception as e:
            logger.error(f"[{phase}] ? CRITICAL ERROR: {e}", exc_info=True)
            return None
        
    def _get_regime_multiplier(
        self,
        regime: str,
    ) -> float:
        """
        ضریب فاصله/ریسک متناظر با رژیم بازار را برمی‌گرداند.
        """
        phase = "AEI_REGIME_MULTIPLIER"

        multipliers = {
            "STRONG_TRENDING_UP": 0.8,
            "STRONG_TRENDING_DOWN": 0.8,
            "TRENDING_UP": 0.9,
            "TRENDING_DOWN": 0.9,
            "RANGE": 1.2,
            "RANGING": 1.2,
            "VOLATILE_RANGE": 1.3,
            "VOLATILE_TRENDING": 1.2,
            "PANIC": 1.5,
            "OVERBOUGHT_REVERSAL": 1.1,
            "OVERSOLD_REVERSAL": 1.1,
            "BREAKOUT": 0.9,
            "VOLATILITY_EXPANSION": 1.2,
            "EXPANSION": 1.2,
            "VOLATILITY_COMPRESSION": 0.8,
            "COMPRESSION": 0.8,
            "NORMAL": 1.0,
        }

        regime_value = str(regime or "NORMAL").strip().upper()
        multiplier = float(
            multipliers.get(regime_value, 1.0)
        )

        logger.debug(
            "[%s] %s -> %.2f",
            phase,
            regime_value,
            multiplier,
        )
        return multiplier
        
    def _calculate_fallback_size(
        self,
        current_price: float,
        stop_loss: float,
        context: Dict,
    ) -> float:
        """
        B-08 اصلاح: ارجاع به `phase` (نامتعریف) حذف شد تا NameError دیگر
        در debug-log نخورد و مقدار واقعی برگردد.
        """
        try:
            balance = float(context.get("account_balance", 10000))
            risk_pct = float(self._max_risk_per_trade)
            risk_amount = balance * risk_pct
            stop_distance = abs(float(current_price) - float(stop_loss))

            if stop_distance > 0:
                size = risk_amount / stop_distance
            else:
                size = (balance * 0.02) / (float(current_price) * 0.01)

            logger.debug(
                "AEI fallback size — Balance: $%.2f, Risk: %.2f%%, Size: %.2f",
                balance,
                risk_pct * 100,
                size,
            )
            return max(0.01, min(10.0, size))
        except Exception as e:
            logger.error("AEI fallback size failed: %s", e, exc_info=True)
            return 0.01
            
class Decision(Enum):
    STRONG_BUY = "STRONG_BUY"
    BUY = "BUY"
    HOLD = "HOLD"
    SELL = "SELL"
    STRONG_SELL = "STRONG_SELL"
    CLOSE_LONG = "CLOSE_LONG"
    CLOSE_SHORT = "CLOSE_SHORT"
    CLOSE_ALL = "CLOSE_ALL"
    REDUCE_LONG = "REDUCE_LONG"
    REDUCE_SHORT = "REDUCE_SHORT"


@dataclass
class MetaDecision:
    """????? ????? ????? ???"""
    decision: Decision
    confidence: float  # 0.0 - 1.0
    reason: str
    components: Dict[str, Any] = field(default_factory=dict)
    adjusted_parameters: Dict[str, Any] = field(default_factory=dict)
    timestamp: datetime = field(default_factory=datetime.now)


class MetaDecisionEngine:
    """
    +------------------------------------------------------------------------------+
    ¦         META DECISION ENGINE (MDE) - WALL STREET QUANT EDITION V4.1         ¦
    ¦                      ✅ FIXED: StrategyScoreBooster integration              ¦
    ¦                      ✅ FIXED: Component access                             ¦
    +------------------------------------------------------------------------------+
    """
    
    def __init__(self, config: Dict[str, Any] = None):
        self.config = config or {}
        self._decision_weights = self._load_decision_weights()
        self._last_decision: Optional[MetaDecision] = None
        self._decision_history: List[MetaDecision] = []
        self._learning_rate = self.config.get('learning_rate', 0.05)
        self._min_weight = self.config.get('min_weight', 0.05)
        self._max_weight = self.config.get('max_weight', 0.50)
        
        # ✅ FIXED: Store booster reference
        self._score_booster = None

        logger.info("✅ MetaDecisionEngine V4.1 initialized")

    def set_score_booster(self, booster):
        """✅ NEW: Set the strategy score booster"""
        self._score_booster = booster
        logger.info("✅ StrategyScoreBooster connected to MDE")

    async def decide(self, context: Dict[str, Any]) -> MetaDecision:
        """
        +------------------------------------------------------------------------------+
        ¦         DECIDE - WITH STRATEGY SCORE BOOSTER INTEGRATION                     ¦
        ¦                      ✅ FIXED V4.1: Proper booster handling                  ¦
        +------------------------------------------------------------------------------+
        """
        phase = "MDE_DECIDE_V4.1"
        start_time = time.time()
        
        try:
            logger.info(f"[{phase}] ---------------------------------------------------------------")
            logger.info(f"[{phase}] 🔍 ENTRY: decide for {context.get('symbol', 'Unknown')}")
            
            # ========== PHASE 1: SCORE COMPONENTS ==========
            logger.info(f"[{phase}] 📊 [1/6] Scoring components...")
            decision_scores = self._score_components(context)
            logger.info(f"[{phase}] ✅ Scores: {decision_scores}")
            
            # ========== PHASE 2: COMBINE SCORES WITH WEIGHTS ==========
            logger.info(f"[{phase}] 📊 [2/6] Combining scores with weights...")
            final_score = self._combine_scores(decision_scores)
            logger.info(f"[{phase}] ✅ Final Score: {final_score:.3f}")
            
            # ========== PHASE 3: GET ORCHESTRATOR SIGNAL ==========
            logger.info(f"[{phase}] 📊 [3/6] Getting orchestrator signal...")
            orchestrator_signal = context.get('unified_signal', {})
            orchestrator_decision = orchestrator_signal.get('decision', 'HOLD')
            orchestrator_confidence = orchestrator_signal.get('confidence', 0.5)
            logger.info(f"[{phase}] ✅ Orchestrator: {orchestrator_decision} (conf={orchestrator_confidence:.2%})")
            
            # ========== PHASE 4: APPLY STRATEGY SCORE BOOSTER (FIXED) ==========
            logger.info(f"[{phase}] 📊 [4/6] Applying strategy score booster...")
            
            # ✅ FIXED: Use stored booster reference
            booster = self._score_booster
            
            if booster is not None and orchestrator_decision not in ['HOLD', 'STRONG_HOLD']:
                try:
                    # ✅ FIXED: Check if booster has the method
                    if hasattr(booster, 'apply_historical_scores'):
                        strategy_details = context.get('strategy_details', {})
                        boosted_signal, boosted_conf, boost_details = booster.apply_historical_scores(
                            final_signal=orchestrator_decision,
                            final_confidence=orchestrator_confidence,
                            strategy_details=strategy_details
                        )
                        if boost_details.get('total_adjustment', 0) != 0:
                            logger.info(f"[{phase}] 📊 Score booster applied: {orchestrator_decision} ({orchestrator_confidence:.2%}) → {boosted_signal} ({boosted_conf:.2%})")
                            orchestrator_decision = boosted_signal
                            orchestrator_confidence = boosted_conf
                    else:
                        logger.warning(f"[{phase}] ⚠️ Booster missing apply_historical_scores method")
                except Exception as booster_err:
                    logger.warning(f"[{phase}] ⚠️ Score booster error: {booster_err}")
            else:
                if booster is None:
                    logger.debug(f"[{phase}] ℹ️ No score booster configured")
                else:
                    logger.debug(f"[{phase}] ℹ️ Signal is HOLD, skipping booster")
            
            # ========== PHASE 5: DETERMINE DECISION ==========
            logger.info(f"[{phase}] 📊 [5/6] Determining final decision...")
            decision, confidence, reason = self._determine_decision(
                final_score=final_score,
                context=context,
                orchestrator_decision=orchestrator_decision,
                orchestrator_confidence=orchestrator_confidence
            )
            
            # ========== PHASE 6: ADJUST PARAMETERS ==========
            logger.info(f"[{phase}] 📊 [6/6] Adjusting parameters...")
            adjusted_params = self._adjust_parameters(decision, context)
            
            # ========== BUILD META DECISION ==========
            meta_decision = MetaDecision(
                decision=decision,
                confidence=confidence,
                reason=reason,
                components=decision_scores,
                adjusted_parameters=adjusted_params
            )
            
            self._last_decision = meta_decision
            self._decision_history.append(meta_decision)
            
            elapsed = (time.time() - start_time) * 1000
            logger.info(f"[{phase}] ✅ Final Decision: {decision.value} (conf={confidence:.2%})")
            logger.info(f"[{phase}]    Reason: {reason}")
            logger.info(f"[{phase}]    Elapsed: {elapsed:.1f}ms")
            logger.info(f"[{phase}] ---------------------------------------------------------------")
            
            return meta_decision
            
        except Exception as e:
            logger.error(f"[{phase}] ❌ MDE decision error: {e}", exc_info=True)
            return MetaDecision(
                decision=Decision.HOLD,
                confidence=0.5,
                reason=f"Error in MDE: {str(e)}",
                components={}
            )
            
    def _load_decision_weights(self) -> Dict[str, float]:
        """???????? ??????? ?? ??? ?? .env ?? ?????? ???????"""
        try:
            import os
            from dotenv import load_dotenv
            load_dotenv()
            
            weights = {
                'unified_signal': float(os.getenv("MDE_WEIGHT_UNIFIED_SIGNAL", "0.25")),
                'market_structure': float(os.getenv("MDE_WEIGHT_MARKET_STRUCTURE", "0.15")),
                'volume_flow': float(os.getenv("MDE_WEIGHT_VOLUME_FLOW", "0.15")),
                'divergence': float(os.getenv("MDE_WEIGHT_DIVERGENCE", "0.15")),
                'portfolio_risk': float(os.getenv("MDE_WEIGHT_PORTFOLIO_RISK", "0.10")),
                'strategy_metadata': float(os.getenv("MDE_WEIGHT_STRATEGY_METADATA", "0.10")),
                'symbol_dna': float(os.getenv("MDE_WEIGHT_SYMBOL_DNA", "0.10")),
            }
            
            total = sum(weights.values())
            if total > 0:
                weights = {k: v / total for k, v in weights.items()}
            
            return weights
            
        except Exception as e:
            logger.warning(f"Could not load weights from .env, using defaults: {e}")
            return {
                'unified_signal': 0.25,
                'market_structure': 0.15,
                'volume_flow': 0.15,
                'divergence': 0.15,
                'portfolio_risk': 0.10,
                'strategy_metadata': 0.10,
                'symbol_dna': 0.10,
            }

    def get_weights(self) -> Dict[str, float]:
        """Return the current decision weights."""
        return self._decision_weights.copy()

    def set_weights(self, new_weights: Dict[str, float]) -> None:
        """Set new decision weights with validation and normalization."""
        if not new_weights:
            return
        
        # Validate keys
        allowed_keys = set(self._decision_weights.keys())
        invalid_keys = set(new_weights.keys()) - allowed_keys
        if invalid_keys:
            logger.warning(f"Invalid weight keys ignored: {invalid_keys}")
        
        # Update only allowed keys
        for key in allowed_keys:
            if key in new_weights:
                self._decision_weights[key] = new_weights[key]
            elif key not in self._decision_weights:
                self._decision_weights[key] = 0.0
        
        # Normalize
        total = sum(self._decision_weights.values())
        if total > 0:
            self._decision_weights = {k: v / total for k, v in self._decision_weights.items()}
        
        logger.info(f"Decision weights updated via set_weights: {self._decision_weights}")

    def _score_components(self, context: Dict) -> Dict[str, float]:
        """????????? ?? ?? ??? (????? ?? -1 ?? 1)"""
        scores = {}
        
        try:
            # 1. Unified Signal from Orchestrator
            unified = context.get('unified_signal', {})
            signal_val = unified.get('signal', 'HOLD')
            confidence = unified.get('confidence', 0.5)
            scores['unified_signal'] = self._signal_to_score(signal_val) * confidence

            # 2. Market Structure
            structure = context.get('market_structure', {})
            trend = structure.get('current_trend', 'NEUTRAL')
            trend_strength = structure.get('trend_strength', 0.5)
            is_range = structure.get('is_range', False)
            if is_range:
                scores['market_structure'] = 0.0
            elif trend == 'UP':
                scores['market_structure'] = trend_strength
            elif trend == 'DOWN':
                scores['market_structure'] = -trend_strength
            else:
                scores['market_structure'] = 0.0

            # 3. Volume Flow
            volume = context.get('volume_flow', {})
            bull = volume.get('order_flow_bullish', 0)
            bear = volume.get('order_flow_bearish', 0)
            scores['volume_flow'] = np.clip(bull - bear, -1.0, 1.0)

            # 4. Divergence
            divergence = context.get('divergence_analysis', {})
            bull_div = divergence.get('bullish_score', 0)
            bear_div = divergence.get('bearish_score', 0)
            scores['divergence'] = np.clip(bull_div - bear_div, -1.0, 1.0)

            # 5. Portfolio Risk
            portfolio = context.get('portfolio_risk', {})
            if isinstance(portfolio, dict):
                is_allowed = portfolio.get('is_trading_allowed', True)
                if not is_allowed:
                    scores['portfolio_risk'] = -0.8
                else:
                    scores['portfolio_risk'] = 0.0
            else:
                scores['portfolio_risk'] = 0.0

            # 6. Strategy Metadata
            strategy_meta = context.get('strategy_metadata', {})
            if isinstance(strategy_meta, dict):
                win_rate = strategy_meta.get('win_rate', 0.5)
                scores['strategy_metadata'] = win_rate - 0.5
            else:
                scores['strategy_metadata'] = 0.0

            # 7. Symbol DNA
            symbol_dna = context.get('symbol_dna', {})
            if isinstance(symbol_dna, dict):
                volatility = symbol_dna.get('volatility', 0.02)
                if volatility > 0.04:
                    scores['symbol_dna'] = -0.3
                elif volatility < 0.01:
                    scores['symbol_dna'] = 0.2
                else:
                    scores['symbol_dna'] = 0.0
            else:
                scores['symbol_dna'] = 0.0

        except Exception as e:
            logger.error(f"Component scoring error: {e}")
            for key in self._decision_weights.keys():
                scores.setdefault(key, 0.0)
        
        return scores

    def _signal_to_score(self, signal: str) -> float:
        """????? ?????? ?? ?? ??? ??? -1 ? 1"""
        signal_map = {
            'STRONG_BUY': 1.0, 'BUY': 0.7, 'WEAK_BUY': 0.3,
            'HOLD': 0.0, 'STRONG_HOLD': 0.0,
            'SELL': -0.7, 'STRONG_SELL': -1.0, 'WEAK_SELL': -0.3
        }
        return signal_map.get(signal, 0.0)

    def _combine_scores(self, scores: Dict[str, float]) -> float:
        """????? ???????? ?? ??????? ????????"""
        final_score = 0.0
        total_weight = 0.0
        
        for component, weight in self._decision_weights.items():
            score = scores.get(component, 0.0)
            final_score += score * weight
            total_weight += weight
        
        if total_weight > 0:
            final_score /= total_weight
        
        return np.clip(final_score, -1.0, 1.0)

    def _determine_decision(
        self,
        final_score: float,
        context: Dict,
        orchestrator_decision: str,
        orchestrator_confidence: float,
    ) -> Tuple[Decision, float, str]:
        """
        +--------------------------------------------------------------------------+
        ¦  DETERMINE DECISION - WITH ORCHESTRATOR INTEGRATION                      ¦
        ¦  B-06 FIXED: CLOSE فقط وقتی سیگنال در جهت «مخالف» پوزیشن باز باشد.     ¦
        +--------------------------------------------------------------------------+
        """
        phase = "MDE_DETERMINE_DECISION_V4"
        try:
            logger.info(f"[{phase}] Determining final decision...")
            logger.info(f"[{phase}]    Final Score: {final_score:.3f}")
            logger.info(
                f"[{phase}]    Orchestrator: {orchestrator_decision} "
                f"(conf={orchestrator_confidence:.2%})"
            )

            confidence = max(orchestrator_confidence, abs(final_score))

            # ── بررسی محدودیت ریسک پرتفوی ──
            portfolio = context.get("portfolio_risk", {})
            if isinstance(portfolio, dict):
                if not portfolio.get("is_trading_allowed", True):
                    logger.info(f"[{phase}] ❌ Portfolio risk limit exceeded")
                    return Decision.HOLD, 0.5, "Portfolio risk limit exceeded"

            # ── بررسی وجود پوزیشن ──
            has_position = context.get("has_position", False)
            position_type = context.get("position_type", None)
            position_pnl = context.get("position_pnl", 0.0)

            if has_position:
                # ══════════════════════════════════════════════════════════════
                # B-06 FIX: SELL ⇒ بستن LONG (نه SHORT)
                #          BUY  ⇒ بستن SHORT (نه LONG)
                # ══════════════════════════════════════════════════════════════
                if (
                    orchestrator_decision in ["STRONG_SELL", "SELL"]
                    and final_score <= -0.5
                ):
                    if position_type == "BUY":
                        return (
                            Decision.CLOSE_LONG,
                            confidence,
                            "Orchestrator sell signal, closing long",
                        )
                    # نکته: اگر position_type == "SELL" بود، هم‌جهت است ⇒ نباید ببندد

                if (
                    orchestrator_decision in ["STRONG_BUY", "BUY"]
                    and final_score >= 0.5
                ):
                    if position_type == "SELL":
                        return (
                            Decision.CLOSE_SHORT,
                            confidence,
                            "Orchestrator buy signal, closing short",
                        )
                    # نکته: اگر position_type == "BUY" بود، هم‌جهت است ⇒ نباید ببندد

                # ── Stop loss / Take profit ──
                if position_pnl < -0.05:
                    if position_type == "BUY":
                        return Decision.CLOSE_LONG, 0.7, "Stop loss triggered"
                    elif position_type == "SELL":
                        return Decision.CLOSE_SHORT, 0.7, "Stop loss triggered"

                if position_pnl > 0.08:
                    if position_type == "BUY":
                        return Decision.CLOSE_LONG, 0.7, "Take profit triggered"
                    elif position_type == "SELL":
                        return Decision.CLOSE_SHORT, 0.7, "Take profit triggered"

                # ── سیگنال ضعیف ⇒ HOLD ──
                if abs(final_score) < 0.3 and orchestrator_confidence < 0.55:
                    return Decision.HOLD, 0.5, "Weak signal, holding position"

            # ══════════════════════════════════════════════════════════════════
            # منطق پوزیشن جدید
            # ══════════════════════════════════════════════════════════════════
            max_positions = context.get("max_positions", 100)
            current_positions = context.get("current_positions", 0)
            if current_positions >= max_positions:
                return Decision.HOLD, 0.5, "Position limit reached"

            # ── Orchestrator primary ──
            if (
                orchestrator_decision in ["STRONG_BUY", "STRONG_SELL"]
                and orchestrator_confidence >= 0.70
            ):
                decision = (
                    Decision.STRONG_BUY
                    if "BUY" in orchestrator_decision
                    else Decision.STRONG_SELL
                )
                return (
                    decision,
                    orchestrator_confidence,
                    f"Orchestrator strong signal: {orchestrator_decision}",
                )

            if (
                orchestrator_decision in ["BUY", "SELL"]
                and orchestrator_confidence >= 0.60
            ):
                decision = (
                    Decision.BUY if "BUY" in orchestrator_decision else Decision.SELL
                )
                return (
                    decision,
                    orchestrator_confidence,
                    f"Orchestrator signal: {orchestrator_decision}",
                )

            # ── Fallback به امتیاز ──
            if final_score >= 0.7:
                return Decision.STRONG_BUY, confidence, "Strong buy signal from score"
            elif final_score <= -0.7:
                return Decision.STRONG_SELL, confidence, "Strong sell signal from score"
            elif final_score >= 0.4:
                return Decision.BUY, confidence, "Buy signal from score"
            elif final_score <= -0.4:
                return Decision.SELL, confidence, "Sell signal from score"

            return Decision.HOLD, 0.5, "No strong signal"

        except Exception as e:
            logger.error(
                f"[{phase}] ❌ Decision determination error: {e}", exc_info=True
            )
            return Decision.HOLD, 0.5, f"Error: {str(e)}"
        
    def _adjust_parameters(
        self,
        decision: Decision,
        context: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        پارامترهای اجرایی را بر اساس تصمیم و وضعیت بازار تولید می‌کند.
        """
        phase = "MDE_ADJUST_PARAMETERS"
        params: Dict[str, Any] = {}

        try:
            if not isinstance(context, dict):
                raise TypeError("context must be a dictionary")

            directional_decisions = {
                Decision.BUY,
                Decision.STRONG_BUY,
                Decision.SELL,
                Decision.STRONG_SELL,
            }

            if decision in directional_decisions:
                symbol_dna = context.get("symbol_dna", {})
                if not isinstance(symbol_dna, dict):
                    symbol_dna = {}

                volatility = float(
                    symbol_dna.get("volatility", 0.02)
                )
                if not math.isfinite(volatility):
                    volatility = 0.02
                volatility = max(0.0, volatility)

                current_price = float(
                    context.get("current_price", 0.0) or 0.0
                )
                atr_default = (
                    current_price * 0.01
                    if current_price > 0.0
                    else 0.01
                )
                atr = float(
                    context.get("atr", atr_default)
                    or atr_default
                )

                if not math.isfinite(atr) or atr <= 0.0:
                    atr = atr_default

                is_strong = decision in {
                    Decision.STRONG_BUY,
                    Decision.STRONG_SELL,
                }
                sl_multiplier = 1.2 if is_strong else 1.8
                tp_multiplier = 2.5 if is_strong else 1.8

                confidence = float(
                    context.get("confidence", 0.5)
                )
                if not math.isfinite(confidence):
                    confidence = 0.5
                confidence = float(
                    np.clip(confidence, 0.0, 1.0)
                )

                params["stop_loss_distance"] = (
                    atr * sl_multiplier
                )
                params["take_profit_distance"] = (
                    atr * tp_multiplier
                )
                params["position_size_risk"] = float(
                    np.clip(
                        0.01
                        + (confidence - 0.5) * 0.02,
                        0.005,
                        0.03,
                    )
                )
                params["trailing_stop_pct"] = (
                    0.015 if is_strong else None
                )
                params["profit_lock_pct"] = (
                    0.01 if is_strong else None
                )
                params["execution_algorithm"] = (
                    "TWAP"
                    if volatility > 0.03
                    else "SNAPSHOT"
                )

            elif decision in {
                Decision.CLOSE_LONG,
                Decision.CLOSE_SHORT,
                Decision.CLOSE_ALL,
            }:
                params["close_all"] = (
                    decision == Decision.CLOSE_ALL
                )
                params["close_side"] = (
                    "LONG"
                    if decision == Decision.CLOSE_LONG
                    else "SHORT"
                    if decision == Decision.CLOSE_SHORT
                    else "ALL"
                )
                params["close_reason"] = (
                    f"MDE decision: {decision.value}"
                )

            elif decision in {
                Decision.REDUCE_LONG,
                Decision.REDUCE_SHORT,
            }:
                params["reduce_size_pct"] = 0.5
                params["reduce_side"] = (
                    "LONG"
                    if decision == Decision.REDUCE_LONG
                    else "SHORT"
                )
                params["reduce_reason"] = (
                    f"MDE decision: {decision.value}"
                )

            return params

        except (
            TypeError,
            ValueError,
            OverflowError,
        ) as exc:
            logger.error(
                "[%s] Parameter adjustment error: %s",
                phase,
                exc,
                exc_info=True,
            )
            return {}
            
    def update_weights(self, new_weights: Dict[str, float]):
        """??????????? ?????? ???? Continuous Learning Engine"""
        try:
            for component, weight in new_weights.items():
                if component in self._decision_weights:
                    old = self._decision_weights[component]
                    new = old + self._learning_rate * (weight - old)
                    self._decision_weights[component] = np.clip(new, self._min_weight, self._max_weight)
            
            total = sum(self._decision_weights.values())
            if total > 0:
                self._decision_weights = {k: v / total for k, v in self._decision_weights.items()}
            
            logger.info(f"Weights updated: {self._decision_weights}")
        except Exception as e:
            logger.error(f"Weight update error: {e}")

    def get_decision_history(self, limit: int = 100) -> List[MetaDecision]:
        """?????? ??????? ???????"""
        return self._decision_history[-limit:]

    def get_last_decision(self) -> Optional[MetaDecision]:
        """?????? ????? ?????"""
        return self._last_decision
         
class PortfolioIntelligenceEngine:
    """
    +------------------------------------------------------------------------------+
    ¦         PORTFOLIO INTELLIGENCE ENGINE (PIE) - WALL STREET QUANT EDITION V3.0¦
    ¦                      ? FULLY INTEGRATED WITH RISK MANAGER                 ¦
    ¦                      ? DYNAMIC CORRELATION MATRIX                         ¦
    ¦                      ? SECTOR AND ASSET CLASS DIVERSIFICATION             ¦
    +------------------------------------------------------------------------------+
    """
    def __init__(self, risk_manager: 'PortfolioRiskManager', config: Dict[str, Any] = None):
        self.risk_manager = risk_manager
        self.config = config or {}
        self._max_correlation_threshold = self.config.get('max_correlation', 0.30)
        self._max_sector_exposure = self.config.get('max_sector_exposure', 0.40)
        self._min_diversification_score = self.config.get('min_diversification', 0.60)
        self._concentration_limit = self.config.get('concentration_limit', 0.25)
        self._risk_budget = self.config.get('risk_budget', 0.10)
        
        # Cache for correlation matrix
        self._correlation_cache: Dict[str, Dict[str, float]] = {}
        self._cache_timestamp = None
        self._cache_ttl_seconds = 300  # 5 minutes
        
        # Sector mapping (can be extended)
        self._sector_map: Dict[str, str] = {}
        self._asset_class_map: Dict[str, str] = {}
        
        logger.info("? PortfolioIntelligenceEngine V3.0 initialized")

    # ========================================================================
    # SECTION 1: ASSESS NEW TRADE (FIXED)
    # ========================================================================
    async def assess_new_trade(
        self,
        symbol: str,
        direction: str,
        estimated_risk: float,
        market_context: Dict[str, Any],
    ) -> Tuple[bool, str, float]:
        """
        امکان افزودن معامله جدید را با رفتار fail-closed بررسی می‌کند.
        """
        phase = "PIE_ASSESS_TRADE_SAFE"

        try:
            symbol_value = str(symbol or "").strip().upper()
            direction_value = str(direction or "").strip().upper()

            if not symbol_value:
                return False, "Missing symbol", 0.0

            if direction_value not in {"BUY", "SELL"}:
                return False, "Invalid trade direction", 0.0

            try:
                risk_value = float(estimated_risk)
            except (TypeError, ValueError):
                return False, "Invalid estimated risk", 0.0

            if not math.isfinite(risk_value) or risk_value < 0.0:
                return False, "Estimated risk must be finite and non-negative", 0.0

            if not isinstance(market_context, dict):
                return False, "market_context must be a dictionary", 0.0

            active_positions = self._get_active_positions()
            if not active_positions:
                return True, "No active positions", 1.0

            correlation_allowed, correlation, violators = (
                await self._check_correlation(
                    symbol_value,
                    active_positions,
                )
            )
            if not correlation_allowed:
                return (
                    False,
                    f"High correlation ({correlation:.2f}) with {violators}",
                    0.0,
                )

            sector = self._get_sector(
                symbol_value,
                market_context,
            )
            sector_allowed, sector_exposure = (
                await self._check_sector_exposure(
                    sector,
                    active_positions,
                )
            )
            if not sector_allowed:
                return (
                    False,
                    f"Sector exposure ({sector_exposure:.1%}) exceeds limit",
                    0.0,
                )

            asset_class = self._get_asset_class(
                symbol_value,
                market_context,
            )
            asset_allowed, class_exposure = (
                await self._check_asset_class_exposure(
                    asset_class,
                    active_positions,
                )
            )
            if not asset_allowed:
                return (
                    False,
                    f"Asset class exposure ({class_exposure:.1%}) exceeds limit",
                    0.0,
                )

            diversification_score = (
                self._calculate_diversification_score(
                    active_positions
                )
            )
            if (
                diversification_score
                < self._min_diversification_score
            ):
                return (
                    False,
                    f"Low diversification ({diversification_score:.2f})",
                    0.0,
                )

            concentration_risk = (
                self._calculate_concentration_risk(
                    active_positions
                )
            )
            if concentration_risk > self._concentration_limit:
                return (
                    False,
                    f"High concentration ({concentration_risk:.1%})",
                    0.0,
                )

            position_multiplier = (
                await self._calculate_position_multiplier(
                    risk_value,
                    active_positions,
                )
            )

            if not math.isfinite(position_multiplier):
                return False, "Invalid position multiplier", 0.0

            position_multiplier = float(
                np.clip(position_multiplier, 0.0, 1.0)
            )

            diversification_adjustment = float(
                np.clip(
                    0.8 + diversification_score * 0.2,
                    0.8,
                    1.0,
                )
            )
            final_multiplier = float(
                np.clip(
                    position_multiplier
                    * diversification_adjustment,
                    0.0,
                    1.0,
                )
            )

            if final_multiplier <= 0.0:
                return False, "Risk budget exhausted", 0.0

            return (
                True,
                "Portfolio check passed",
                final_multiplier,
            )

        except Exception as exc:
            logger.error(
                "[%s] Portfolio assessment failed: %s",
                phase,
                exc,
                exc_info=True,
            )
            return (
                False,
                f"Portfolio assessment error: {exc}",
                0.0,
            )
            
    # ========================================================================
    # SECTION 2: CORRELATION CHECK (FIXED)
    # ========================================================================
    async def _check_correlation(self, symbol: str, positions: List) -> Tuple[bool, float, List[str]]:
        """????? ??????? ?? ?????????? ????"""
        violators = []
        max_corr = 0.0
        
        # ?????? ?? ?????? correlation matrix
        corr_matrix = await self._get_correlation_matrix(positions)
        
        for pos in positions:
            pos_symbol = pos.get('symbol', '')
            if pos_symbol == symbol:
                continue
            
            corr = corr_matrix.get(symbol, {}).get(pos_symbol, 0.0)
            abs_corr = abs(corr)
            max_corr = max(max_corr, abs_corr)
            
            if abs_corr > self._max_correlation_threshold:
                violators.append(pos_symbol)
        
        return len(violators) == 0, max_corr, violators

    # ========================================================================
    # SECTION 3: SECTOR EXPOSURE (NEW)
    # ========================================================================
    async def _check_sector_exposure(self, sector: str, positions: List) -> Tuple[bool, float]:
        """????? ????? exposure ?? ?? ????? ???"""
        if not positions or not sector:
            return True, 0.0
        
        total_value = sum(self._get_position_value(p) for p in positions)
        sector_value = sum(
            self._get_position_value(p) 
            for p in positions 
            if self._get_sector(p.get('symbol', ''), {}) == sector
        )
        
        exposure_ratio = sector_value / (total_value + 1e-8)
        return exposure_ratio < self._max_sector_exposure, exposure_ratio

    # ========================================================================
    # SECTION 4: ASSET CLASS EXPOSURE (NEW)
    # ========================================================================
    async def _check_asset_class_exposure(self, asset_class: str, positions: List) -> Tuple[bool, float]:
        """????? ????? exposure ?? ?? ???? ?????? ???"""
        if not positions or not asset_class:
            return True, 0.0
        
        total_value = sum(self._get_position_value(p) for p in positions)
        class_value = sum(
            self._get_position_value(p)
            for p in positions
            if self._get_asset_class(p.get('symbol', ''), {}) == asset_class
        )
        
        exposure_ratio = class_value / (total_value + 1e-8)
        return exposure_ratio < 0.50, exposure_ratio  # 50% max per asset class

    # ========================================================================
    # SECTION 5: DIVERSIFICATION SCORE (FIXED)
    # ========================================================================
    def _calculate_diversification_score(self, positions: List) -> float:
        """?????? ?????? ????????? ?????????"""
        if not positions:
            return 1.0
        
        if len(positions) < 2:
            return 1.0
        
        # ????? ??????? ????????????
        symbols = [p.get('symbol', '') for p in positions if p.get('symbol')]
        unique_symbols = len(set(symbols))
        
        # ?????? ????: ???? ??????? ???????????? ?? ??
        base_score = unique_symbols / len(positions) if positions else 1.0
        
        # ?????? ??????: ???? ?? ???????
        sectors = [self._get_sector(p.get('symbol', ''), {}) for p in positions if p.get('symbol')]
        unique_sectors = len(set(sectors))
        sector_score = unique_sectors / max(len(positions), 1)
        
        # ?????? ???? ??????
        asset_classes = [self._get_asset_class(p.get('symbol', ''), {}) for p in positions if p.get('symbol')]
        unique_classes = len(set(asset_classes))
        class_score = unique_classes / max(len(positions), 1)
        
        # ????? ????????
        final_score = base_score * 0.5 + sector_score * 0.3 + class_score * 0.2
        return min(1.0, final_score)

    # ========================================================================
    # SECTION 6: CONCENTRATION RISK (FIXED)
    # ========================================================================
    def _calculate_concentration_risk(self, positions: List) -> float:
        """?????? ???? ????? ?? ?? ??????"""
        if not positions:
            return 0.0
        
        values = [self._get_position_value(p) for p in positions]
        total_value = sum(values)
        if total_value <= 0:
            return 0.0
        
        max_value = max(values)
        return max_value / total_value

    # ========================================================================
    # SECTION 7: POSITION MULTIPLIER (FIXED)
    # ========================================================================
    async def _calculate_position_multiplier(self, estimated_risk: float, positions: List) -> float:
        """?????? ???? ????? ??? ?? ???? ???? ?? ?????????"""
        total_risk = sum(self._get_position_risk(p) for p in positions)
        portfolio_risk_ratio = (total_risk + estimated_risk) / self.risk_manager.current_balance if self.risk_manager else 0
        
        if portfolio_risk_ratio > self._risk_budget * 1.2:
            return 0.3
        elif portfolio_risk_ratio > self._risk_budget:
            return 0.6
        elif portfolio_risk_ratio > self._risk_budget * 0.6:
            return 0.8
        return 1.0

    # ========================================================================
    # SECTION 8: CORRELATION MATRIX (NEW)
    # ========================================================================
    async def _get_correlation_matrix(self, positions: List) -> Dict[str, Dict[str, float]]:
        """?????? ?? ?????? ?????? ???????"""
        # Check cache
        import time
        current_time = time.time()
        if (self._cache_timestamp and 
            current_time - self._cache_timestamp < self._cache_ttl_seconds and
            self._correlation_cache):
            return self._correlation_cache
        
        # Build symbols list
        symbols = [p.get('symbol', '') for p in positions if p.get('symbol')]
        symbols = list(set(symbols))
        
        if len(symbols) < 2:
            self._correlation_cache = {s: {s: 1.0} for s in symbols}
            self._cache_timestamp = current_time
            return self._correlation_cache
        
        # Get price history from risk manager
        matrix = {}
        for s1 in symbols:
            matrix[s1] = {}
            for s2 in symbols:
                if s1 == s2:
                    matrix[s1][s2] = 1.0
                else:
                    corr = self.risk_manager.get_correlation_between(s1, s2) if self.risk_manager else 0.0
                    matrix[s1][s2] = corr
        
        self._correlation_cache = matrix
        self._cache_timestamp = current_time
        return matrix

    # ========================================================================
    # SECTION 9: HELPER METHODS
    # ========================================================================
    def _get_active_positions(self) -> List:
        """?????? ?????????? ???? ?? risk_manager"""
        if hasattr(self.risk_manager, 'active_positions'):
            positions = self.risk_manager.active_positions
            if positions:
                # Convert to list of dicts if needed
                if hasattr(positions[0], '__dict__'):
                    return [p.__dict__ if hasattr(p, '__dict__') else p for p in positions]
                return positions
        return []

    def _get_position_value(self, position: Dict) -> float:
        """?????? ???? ?? ??????"""
        if isinstance(position, dict):
            return position.get('position_size', 0) * position.get('current_price', 0)
        if hasattr(position, 'position_size') and hasattr(position, 'current_price'):
            return position.position_size * position.current_price
        return 0.0

    def _get_position_risk(self, position: Dict) -> float:
        """?????? ???? ?? ??????"""
        if isinstance(position, dict):
            return position.get('risk_amount', 0.0)
        if hasattr(position, 'risk_amount'):
            return position.risk_amount
        return 0.0

    def _get_sector(self, symbol: str, context: Dict) -> str:
        """?????? ????? ?? ????"""
        if symbol in self._sector_map:
            return self._sector_map[symbol]
        
        # Fallback: detect from symbol
        symbol_upper = symbol.upper()
        if any(x in symbol_upper for x in ['BTC', 'ETH', 'LTC', 'XRP', 'ADA', 'DOT', 'LINK', 'BNB', 'SOL']):
            sector = 'crypto'
        elif any(x in symbol_upper for x in ['XAU', 'XAG', 'GOLD', 'SILVER']):
            sector = 'precious_metals'
        elif any(x in symbol_upper for x in ['WTI', 'OIL', 'BRENT']):
            sector = 'energy'
        elif any(x in symbol_upper for x in ['EUR', 'USD', 'GBP', 'JPY', 'AUD', 'NZD', 'CAD', 'CHF']):
            sector = 'forex'
        else:
            sector = 'other'
        
        self._sector_map[symbol] = sector
        return sector

    def _get_asset_class(self, symbol: str, context: Dict) -> str:
        """?????? ???? ?????? ?? ????"""
        if symbol in self._asset_class_map:
            return self._asset_class_map[symbol]
        
        sector = self._get_sector(symbol, context)
        if sector in ['crypto']:
            asset_class = 'digital_asset'
        elif sector in ['precious_metals', 'energy']:
            asset_class = 'commodity'
        elif sector in ['forex']:
            asset_class = 'currency'
        else:
            asset_class = 'other'
        
        self._asset_class_map[symbol] = asset_class
        return asset_class

class DynamicParameterEstimator:
    """
    +------------------------------------------------------------------------------+
    ¦         DYNAMIC PARAMETER ESTIMATOR - WALL STREET QUANT EDITION             ¦
    ¦                      ? FULLY DYNAMIC - NO HARDCODED VALUES                 ¦
    ¦                      ? BULLETPROOF TRY-EXCEPT BLOCKS                       ¦
    ¦                      ? COMPLETE PHASE LOGGING                             ¦
    +------------------------------------------------------------------------------+
    
    ??? ???? ?????????? ???????? ?? ?? ???? ????? ????? ??????????? ??????.
    """
    def __init__(self, history_file: str = "TRADE/parameter_history.json"):
        """
        Args:
            history_file: ???? ???? ???? ????? ??????? ?????????
        """
        self.history_file = history_file
        self._parameter_history = self._load_history()
        logger.info("? DynamicParameterEstimator initialized")
    
    def _load_history(self) -> Dict:
        """???????? ??????? ????????? ?? ????"""
        try:
            if os.path.exists(self.history_file):
                with open(self.history_file, 'r', encoding='utf-8') as f:
                    return json.load(f)
            return {}
        except Exception as e:
            logger.warning(f"Could not load parameter history: {e}")
            return {}
    
    def _save_history(self):
        """????? ??????? ????????? ?? ????"""
        try:
            os.makedirs(os.path.dirname(self.history_file), exist_ok=True)
            with open(self.history_file, 'w', encoding='utf-8') as f:
                json.dump(self._parameter_history, f, indent=2, default=str)
        except Exception as e:
            logger.error(f"Failed to save parameter history: {e}")
    
    def estimate_parameters(self, df: pd.DataFrame, market_context: Dict) -> Dict[str, Any]:
        """
        ????? ?????????? ????? ?? ???? ???????? ?????
        
        Args:
            df: ???????? ??????
            market_context: ??????? ???? ????? ? ?????
            
        Returns:
            Dict: ?????????? ????????? ???? SL, TP, ??? ?...
        """
        phase = "ESTIMATE_PARAMETERS"
        
        try:
            logger.info(f"[{phase}] ?? Estimating dynamic parameters...")
            
            # ========== PHASE 1: GET MARKET CONTEXT ==========
            regime = market_context.get('regime', 'NORMAL')
            volatility = market_context.get('volatility', 0.02)
            current_price = market_context.get('current_price', 0)
            atr = market_context.get('atr', current_price * 0.01)
            symbol = market_context.get('symbol', 'UNKNOWN')
            
            # ========== PHASE 2: CALCULATE DYNAMIC PARAMETERS ==========
            # 2.1: Stop Loss (?? ???? ATR ? ???? ?????)
            sl_multiplier = self._get_sl_multiplier(regime, volatility)
            stop_loss = atr * sl_multiplier
            
            # 2.2: Take Profit (???? ?? SL)
            tp_ratio = self._get_tp_ratio(regime)
            take_profit = stop_loss * tp_ratio
            
            # 2.3: Position Size (?? ???? ????? ? ??????)
            position_size_pct = self._get_position_size_pct(regime, volatility)
            
            # 2.4: Trailing Stop (?? ???? ????)
            trailing_stop_pct = self._get_trailing_stop_pct(regime)
            
            # 2.5: Activation Profit (????? ??? ???? ????????? ???????)
            activation_profit_pct = self._get_activation_profit(regime)
            
            # ========== PHASE 3: BUILD RESULT ==========
            params = {
                'stop_loss': round(stop_loss, 5),
                'take_profit': round(take_profit, 5),
                'position_size_pct': round(position_size_pct, 4),
                'trailing_stop_pct': round(trailing_stop_pct, 4),
                'activation_profit_pct': round(activation_profit_pct, 4),
                'sl_multiplier': round(sl_multiplier, 2),
                'tp_ratio': round(tp_ratio, 2),
                'regime': regime,
                'volatility': volatility,
                'timestamp': datetime.now().isoformat()
            }
            
            # ========== PHASE 4: UPDATE HISTORY ==========
            if symbol not in self._parameter_history:
                self._parameter_history[symbol] = []
            
            self._parameter_history[symbol].append(params)
            if len(self._parameter_history[symbol]) > 100:
                self._parameter_history[symbol] = self._parameter_history[symbol][-100:]
            
            self._save_history()
            
            logger.info(f"[{phase}] ? Parameters estimated: SL={params['stop_loss']}, TP={params['take_profit']}")
            return params
            
        except Exception as e:
            logger.error(f"[{phase}] ? Error estimating parameters: {e}", exc_info=True)
            # Fallback: ?????????? ????
            return {
                'stop_loss': 0.02,
                'take_profit': 0.04,
                'position_size_pct': 0.02,
                'trailing_stop_pct': 0.015,
                'activation_profit_pct': 0.015,
                'sl_multiplier': 1.5,
                'tp_ratio': 2.0,
                'regime': 'NORMAL',
                'volatility': 0.02,
                'timestamp': datetime.now().isoformat()
            }
    
    def _get_sl_multiplier(self, regime: str, volatility: float) -> float:
        """?????? ???? SL ?? ???? ???? ?????"""
        try:
            # ??????? ???? ????? (?? .env ?? ???????)
            regime_multipliers = {
                'STRONG_TRENDING_UP': 1.0,
                'STRONG_TRENDING_DOWN': 1.0,
                'TRENDING_UP': 1.2,
                'TRENDING_DOWN': 1.2,
                'RANGE': 1.8,
                'VOLATILE_RANGE': 2.0,
                'VOLATILE_TRENDING': 1.5,
                'PANIC': 2.5,
                'OVERBOUGHT_REVERSAL': 1.5,
                'OVERSOLD_REVERSAL': 1.5,
                'BREAKOUT': 1.0,
                'VOLATILITY_EXPANSION': 1.8,
                'VOLATILITY_COMPRESSION': 1.2,
                'NORMAL': 1.5
            }
            
            base_multiplier = regime_multipliers.get(regime, 1.5)
            
            # ????? ?? ???? ?????
            if volatility > 0.03:
                base_multiplier *= 1.2
            elif volatility < 0.01:
                base_multiplier *= 0.8
            
            return max(0.8, min(3.0, base_multiplier))
            
        except Exception:
            return 1.5
    
    def _get_tp_ratio(self, regime: str) -> float:
        """?????? ???? TP ?? SL ?? ???? ???? ?????"""
        try:
            tp_ratios = {
                'STRONG_TRENDING_UP': 2.5,
                'STRONG_TRENDING_DOWN': 2.5,
                'TRENDING_UP': 2.0,
                'TRENDING_DOWN': 2.0,
                'RANGE': 1.5,
                'VOLATILE_RANGE': 1.8,
                'VOLATILE_TRENDING': 2.2,
                'PANIC': 3.0,
                'OVERBOUGHT_REVERSAL': 2.0,
                'OVERSOLD_REVERSAL': 2.0,
                'BREAKOUT': 2.5,
                'VOLATILITY_EXPANSION': 2.0,
                'VOLATILITY_COMPRESSION': 1.8,
                'NORMAL': 2.0
            }
            
            return tp_ratios.get(regime, 2.0)
            
        except Exception:
            return 2.0
    
    def _get_position_size_pct(self, regime: str, volatility: float) -> float:
        """?????? ???? ??? ?????? ?? ???? ???? ?????"""
        try:
            base_pct = 0.02
            
            if regime in ['PANIC', 'VOLATILE_RANGE', 'VOLATILITY_EXPANSION']:
                base_pct *= 0.5
            elif regime in ['RANGE', 'VOLATILE']:
                base_pct *= 0.7
            elif regime in ['BREAKOUT', 'STRONG_TRENDING_UP', 'STRONG_TRENDING_DOWN']:
                base_pct *= 1.2
            elif volatility > 0.04:
                base_pct *= 0.6
            elif volatility < 0.01:
                base_pct *= 1.1
            
            return max(0.005, min(0.05, base_pct))
            
        except Exception:
            return 0.02
    
    def _get_trailing_stop_pct(self, regime: str) -> float:
        """?????? ???? ??????? ????? ?? ???? ???? ?????"""
        try:
            if regime in ['STRONG_TRENDING_UP', 'STRONG_TRENDING_DOWN', 'BREAKOUT']:
                return 0.015
            elif regime in ['TRENDING_UP', 'TRENDING_DOWN']:
                return 0.018
            elif regime in ['RANGE', 'VOLATILE']:
                return 0.025
            else:
                return 0.020
        except Exception:
            return 0.020
    
    def _get_activation_profit(self, regime: str) -> float:
        """?????? ????? ??? ???? ????????? ???????"""
        try:
            if regime in ['STRONG_TRENDING_UP', 'STRONG_TRENDING_DOWN', 'BREAKOUT']:
                return 0.012
            else:
                return 0.015
        except Exception:
            return 0.015
    
    def get_parameter_history(self, symbol: str, limit: int = 50) -> List[Dict]:
        """?????? ??????? ????????? ???? ?? ????"""
        try:
            history = self._parameter_history.get(symbol, [])
            return history[-limit:]
        except Exception:
            return []

