class DrawdownProtection(Enum):
    """??? ?????? ?? ????? Drawdown"""
    NONE = "NONE"                     # ???? ??????
    LIGHT = "LIGHT"                   # ???? 50% ??? ?? ?? 5% drawdown
    MODERATE = "MODERATE"             # ???? ???? ?? ?? 8% drawdown
    SEVERE = "SEVERE"                 # ???? ???? ?? ?? 10% drawdown

def normalize_risk_level(
    value: Union["RiskLevel", str, None],
) -> "RiskLevel":
    """
    هر مقدار ورودی (Enum، str، None) را به RiskLevel امن تبدیل می‌کند.

    - Enum معتبر → همان
    - str معتبر (case-insensitive) → Enum معادل
    - None یا نامعتبر → RiskLevel.MODERATE (پیش‌فرض محافظه‌کارانه)
    """
    if isinstance(value, RiskLevel):
        return value
    if isinstance(value, str):
        try:
            return RiskLevel(value.strip().upper())
        except ValueError:
            pass
    return RiskLevel.MODERATE


def normalize_drawdown_protection(
    value: Union["DrawdownProtection", str, None],
) -> "DrawdownProtection":
    """
    هر مقدار ورودی را به DrawdownProtection امن تبدیل می‌کند.

    - Enum معتبر → همان
    - str معتبر → Enum معادل
    - None یا نامعتبر → DrawdownProtection.MODERATE
    """
    if isinstance(value, DrawdownProtection):
        return value
    if isinstance(value, str):
        try:
            return DrawdownProtection(value.strip().upper())
        except ValueError:
            pass
    return DrawdownProtection.MODERATE
    
@dataclass
class PositionRisk:
    """اطلاعات ریسک و وضعیت یک پوزیشن باز."""

    symbol: str
    position_size: float
    entry_price: float
    current_price: float
    stop_loss: float
    risk_amount: float
    risk_percent: float
    current_pnl: float
    current_pnl_percent: float
    position_type: str = "BUY"
    correlation_risk: float = 0.0
    var_contribution: float = 0.0

    def __post_init__(self) -> None:
        self.symbol = str(self.symbol or "UNKNOWN").upper()
        self.position_type = str(self.position_type or "BUY").upper()

        if self.position_type not in {"BUY", "SELL"}:
            raise ValueError(
                f"position_type must be BUY or SELL, got {self.position_type!r}"
            )

        numeric_fields = {
            "position_size": self.position_size,
            "entry_price": self.entry_price,
            "current_price": self.current_price,
            "stop_loss": self.stop_loss,
            "risk_amount": self.risk_amount,
            "risk_percent": self.risk_percent,
            "current_pnl": self.current_pnl,
            "current_pnl_percent": self.current_pnl_percent,
            "correlation_risk": self.correlation_risk,
            "var_contribution": self.var_contribution,
        }

        for field_name, raw_value in numeric_fields.items():
            try:
                value = float(raw_value)
            except (TypeError, ValueError) as exc:
                raise ValueError(
                    f"{field_name} must be numeric, got {raw_value!r}"
                ) from exc

            if not math.isfinite(value):
                raise ValueError(
                    f"{field_name} must be finite, got {raw_value!r}"
                )

            setattr(self, field_name, value)

        if self.position_size <= 0.0:
            raise ValueError("position_size must be greater than zero")

        if self.entry_price <= 0.0:
            raise ValueError("entry_price must be greater than zero")

        if self.current_price <= 0.0:
            raise ValueError("current_price must be greater than zero")

        if self.stop_loss < 0.0:
            raise ValueError("stop_loss cannot be negative")

        if self.risk_amount < 0.0:
            raise ValueError("risk_amount cannot be negative")

        if self.risk_percent < 0.0:
            raise ValueError("risk_percent cannot be negative")
