    async def update_price_history(self, symbol: str, price: float, timestamp: datetime = None):
        """
        ??????????? ??????? ???? ???? ?????? ???????
        
        Args:
            symbol: ???? ????????
            price: ???? ????
            timestamp: ???? (???????)
        """
        try:
            if symbol not in self.price_history:
                self.price_history[symbol] = []
                self.return_history[symbol] = []
            
            self.price_history[symbol].append(price)
            
            # ?????? ????? ??????
            if len(self.price_history[symbol]) >= 2:
                last_price = self.price_history[symbol][-2]
                if last_price > 0:
                    daily_return = (price - last_price) / last_price
                    self.return_history[symbol].append(daily_return)
            
            # ????? ???? ???????
            max_history = self.correlation_lookback_days * 24  # ??? ?? 24 ???? ?? ???
            if len(self.price_history[symbol]) > max_history:
                self.price_history[symbol] = self.price_history[symbol][-max_history:]
            if len(self.return_history[symbol]) > max_history:
                self.return_history[symbol] = self.return_history[symbol][-max_history:]
            
            # ??????????? ??????? ?????? ???????
            if len(self.return_history[symbol]) >= 20:
                await self._update_correlation_matrix()
                
        except Exception as e:
            logger.error(f"Error updating price history for {symbol}: {e}")
    
    async def _update_correlation_matrix(self):
        """??????????? ?????? ??????? ??? ??????"""
        phase = "CORRELATION_MATRIX"
        
        try:
            symbols = list(self.return_history.keys())
            if len(symbols) < 2:
                return
            
            # ????? ?????? ?????
            min_length = min(len(self.return_history[s]) for s in symbols)
            if min_length < 10:
                return
            
            returns_matrix = []
            for symbol in symbols:
                returns = self.return_history[symbol][-min_length:]
                returns_matrix.append(returns)
            
            returns_array = np.array(returns_matrix)
            
            # ?????? ?????? ???????
            corr_matrix = np.corrcoef(returns_array)
            
            # ????? ?? ???????
            new_correlation_matrix = {}
            for i, sym_i in enumerate(symbols):
                new_correlation_matrix[sym_i] = {}
                for j, sym_j in enumerate(symbols):
                    corr_value = corr_matrix[i, j]
                    # ??? ????
                    if abs(corr_value) < 0.05:
                        corr_value = 0.0
                    new_correlation_matrix[sym_i][sym_j] = corr_value
            
            self.correlation_matrix = new_correlation_matrix
            
            # ????? ?? ??
            self._save_correlation_cache()
            
            logger.debug(f"[{phase}] Updated correlation matrix for {len(symbols)} symbols")
            
        except Exception as e:
            logger.error(f"[{phase}] Error updating correlation matrix: {e}")
    
    def _load_correlation_cache(self):
        """???????? ?????? ??????? ?? ??"""
        try:
            if os.path.exists(self.cache_file):
                with open(self.cache_file, 'r') as f:
                    data = json.load(f)
                    # ????? keys ?? string ?? float ???? ??????
                    self.correlation_matrix = data.get('correlation_matrix', {})
                    logger.info(f"Loaded correlation matrix for {len(self.correlation_matrix)} symbols from cache")
        except Exception as e:
            logger.debug(f"Could not load correlation cache: {e}")
    
    def _save_correlation_cache(self):
        """????? ?????? ??????? ?? ??"""
        try:
            os.makedirs(os.path.dirname(self.cache_file), exist_ok=True)
            with open(self.cache_file, 'w') as f:
                json.dump({
                    'correlation_matrix': self.correlation_matrix,
                    'updated_at': datetime.now().isoformat()
                }, f, indent=2)
        except Exception as e:
            logger.debug(f"Could not save correlation cache: {e}")
    
    # ========================================================================
    # ??? 2: ?????? ??????? ??? ?????????
