# ============================================================================
# THE UNIFIED CLASS
# ============================================================================
class ContinuousLearningEngine:
    """
    V8.0 — موتور یادگیری مستمر یکپارچه (Unified Production-Grade CLE).

    دو مسیر ورودی مکمل هم دارد:
      • process_trade_result(...)  → مسیر مستقیم و سخت‌گیرانه (سازگار با V7.0)
      • add_trade(...)             → مسیر صف‌بندی‌شده، مقاوم در برابر خطا،
                                      با retry خودکار و circuit breaker،
                                      برای یادگیری مستمر بدون توقف و بدون کرش.
    """

    _VALIDATOR_REQUIRED_FIELDS = {'symbol', 'pnl', 'status'}
    _VALIDATOR_VALID_STATUSES = {'CLOSED', 'closed', 'FILLED'}
    _DEFAULT_STRATEGY_FALLBACK = list(CANONICAL_STRATEGY_KEYS)

    def __init__(
        self,
        config: Dict[str, Any] = None,
        event_bus: Any = None,
    ):
        self._config = config or {}
        self._base_dir = Path(self._config.get('base_dir', 'TRADE/CLE'))
        self._processed_positions: Set[int] = set()  # ✅ NEW: Track processed positions
        self._position_cache_file = self._base_dir / "processed_positions.json"
        self.logger = logger
        # ---- هسته اصلی (بدون تغییر نسبت به V7.0) ----
        self._store = AtomicFileStore(self._base_dir)
        self._performance_tracker = StrategyPerformanceTracker(self._store)
        self._weight_optimizer: Optional[WeightOptimizer] = None
        self._TRADES_HISTORY_MAX = 500
        self._mde: Optional[Any] = None
        self._penalty_manager: Optional[Any] = None
        self._signal_file_manager: Optional[Any] = None

        self._processed_trades: Set[str] = set()
        self._processed_file = self._base_dir / "processed_trades.json"
        self._state_lock = asyncio.Lock()

        self._running: bool = False
        self._background_tasks: List[asyncio.Task] = []
        self._logger = logger

        self._learning_rate = self._config.get('learning_rate', 0.05)
        self._min_weight = self._config.get('min_weight', 0.05)
        self._max_weight = self._config.get('max_weight', 0.50)

        self._regime_performance: Dict[str, Dict[str, List[float]]] = defaultdict(
            lambda: {'wins': [], 'pnl': []}
        )

        self._processed_count: int = 0
        self._error_count: int = 0

        # ---- (ادغام‌شده از CLE_TradeRepository) صف/مخزن معاملات ----
        self._trades: Dict[str, Dict[str, Any]] = {}
        self._id_by_status: Dict[CLE_TradeStatus, Set[str]] = {
            status: set() for status in CLE_TradeStatus
        }
        self._repo_max_size = int(self._config.get('repo_max_size', CLE_MAX_HISTORY_SIZE))
        self._repo_lock = asyncio.Lock()

        # ---- (ادغام‌شده از CLE_CircuitBreaker) ----
        self._cb_failure_threshold = int(
            self._config.get('cb_failure_threshold', CLE_CIRCUIT_BREAKER_FAILURE_THRESHOLD)
        )
        self._cb_timeout_seconds = int(
            self._config.get('cb_timeout_seconds', CLE_CIRCUIT_BREAKER_TIMEOUT_SECONDS)
        )
        self._cb_failure_count: int = 0
        self._cb_state: CircuitBreakerState = CircuitBreakerState.CLOSED
        self._cb_state_changed_at: datetime = datetime.now()
        self._cb_lock = asyncio.Lock()

        # ---- (ادغام‌شده از CLE_LearningLoop) حلقه پردازش دسته‌ای ----
        self._event_bus = event_bus
        self._max_batch_size = int(self._config.get('max_batch_size', CLE_MAX_BATCH_SIZE))
        self._interval_seconds = int(self._config.get('interval_seconds', CLE_LEARNING_INTERVAL_SECONDS))
        self._processing_timeout_seconds = int(
            self._config.get('processing_timeout_seconds', CLE_PROCESSING_TIMEOUT_SECONDS)
        )
        self._max_retries = int(self._config.get('max_retries', CLE_MAX_RETRIES))
        self._report_interval_seconds = int(
            self._config.get('report_interval_seconds', CLE_REPORT_INTERVAL_SECONDS)
        )
        # ✅ NEW: Retry mechanism
        self._loop_retry_count = 0
        self._loop_max_retries = 10
        self._loop_retry_backoff_base = 2  # Exponential backoff base
        self._loop_retry_max_delay = 300  # Max 5 minutes
        
        # ✅ NEW: Health tracking
        self._loop_consecutive_failures = 0
        self._loop_max_consecutive_failures = 5
        self._loop_last_success_time = None
        
        # ✅ NEW: Graceful degradation
        self._degradation_mode_active = False
        self._degradation_mode_start_time = None
    
        self._loop_running: bool = False
        self._loop_task: Optional[asyncio.Task] = None
        self._health_check_task: Optional[asyncio.Task] = None
        self._loop_metrics = CLE_Metrics()
        self._shutdown_event = asyncio.Event()
        self._drain_complete = asyncio.Event()
        self._processing_tasks: Set[asyncio.Task] = set()
        self._last_report_time: float = 0.0

        # اجرای خودکار حلقه پس‌زمینه فقط با درخواست صریح در config، تا
        # رفتار پیش‌فرض کدهای موجود که فقط initialize() را صدا می‌زنند تغییر نکند.
        self._auto_start_loop = bool(self._config.get('auto_start_loop', False))
        self._stats: Dict[str, Any] = {
                'total_processed': 0,
                'total_failed': 0,
                'total_skipped': 0,
                'batch_processed': 0,
                'total_processed_batch': 0,
                'total_success_batch': 0,
                'total_errors_batch': 0,
                'total_skipped_batch': 0,
                'last_batch_success_rate': 0.0,
                'critical_errors': 0,
                'last_error': None,
                'last_error_time': None,
                'last_processed_time': None,
                'skipped_due_to_cb': 0,
                'weight_updates': 0,
                'last_weight_update': None,
                'weight_changes_count': 0,
                'weight_update_errors': 0,
                'last_weight_error': None,
                'last_weight_error_time': None,
                'weight_updates_skipped_no_mde': 0,
                'weight_updates_skipped_mde_incompatible': 0,
            }
        
        self._logger.info(f"ContinuousLearningEngine V{CLE_ENGINE_VERSION} initialized")

    async def _generate_comprehensive_diagnostic(self) -> None:
        """
        ✅ NEW: تولید گزارش تشخیصی کامل از PenaltyManager و ارسال به تلگرام
        فراخوانی شده در حلقه یادگیری هر 10 سیکل
        """
        phase = "GENERATE_COMPREHENSIVE_DIAGNOSTIC"
        try:
            if not self._penalty_manager:
                logger.debug(f"[{phase}] PenaltyManager not available")
                return
            
            if not hasattr(self._penalty_manager, 'generate_comprehensive_diagnostic_report'):
                logger.warning(f"[{phase}] PenaltyManager does not have generate_comprehensive_diagnostic_report method")
                return
            
            # تولید گزارش
            report = self._penalty_manager.generate_comprehensive_diagnostic_report()
            
            if report:
                # ارسال به تلگرام
                try:
                    tel_log.trade(report)
                    logger.info(f"[{phase}] ✅ Diagnostic report sent to Telegram")
                except Exception as tel_err:
                    logger.warning(f"[{phase}] ⚠️ Could not send to Telegram: {tel_err}")
                
                # ذخیره در فایل
                try:
                    report_dir = self._base_dir / "reports" / "diagnostic"
                    report_dir.mkdir(parents=True, exist_ok=True)
                    timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
                    report_file = report_dir / f"diagnostic_{timestamp}.txt"
                    with open(report_file, 'w', encoding='utf-8') as f:
                        f.write(report)
                    logger.info(f"[{phase}] ✅ Diagnostic report saved: {report_file.name}")
                except Exception as save_err:
                    logger.warning(f"[{phase}] ⚠️ Could not save report: {save_err}")
            else:
                logger.debug(f"[{phase}] No diagnostic report generated")
                
        except Exception as e:
            logger.error(f"[{phase}] ❌ Error: {e}", exc_info=True)
        
    async def _process_trade_with_retry(
        self,
        trade: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        معامله را با Retry، Circuit Breaker و نتیجه ساختاریافته پردازش
        می‌کند.

        ✅ FIXED V9: `trade_id` استخراج و به `process_trade_result`
        منتقل می‌شود تا در سراسر زنجیره به `strategy_trade_outcomes`
        برسد و از double-counting جلوگیری شود.
        """
        start_time = time.time()
        trade_id = str(
            trade.get("trade_id")
            or trade.get("id")
            or trade.get("signal_id")
            or uuid.uuid4()
        )
        symbol = str(trade.get("symbol") or "UNKNOWN").upper()
        phase = f"PROCESS_TRADE_WITH_RETRY:{symbol}"

        last_error: Optional[str] = None
        attempt_number = 0

        try:
            normalized_trade = self._validate_and_normalize_trade(trade)
            if normalized_trade is None:
                await self._repo_mark_skipped(trade_id)
                self._loop_metrics.total_skipped += 1
                return {
                    "success": False,
                    "skipped": True,
                    "trade_id": trade_id,
                    "attempts": 0,
                    "error": "Trade validation failed",
                }

            # ✅ FIXED: استفاده از trade_id نرمال‌شده (fallback)
            resolved_trade_id = str(
                normalized_trade.get("trade_id")
                or normalized_trade.get("id")
                or trade_id
            )

            pnl_raw = normalized_trade.get("pnl", 0.0)
            try:
                pnl_value = float(pnl_raw)
            except (TypeError, ValueError) as exc:
                raise ValueError(f"Invalid PnL: {pnl_raw!r}") from exc

            if not math.isfinite(pnl_value):
                raise ValueError(
                    f"PnL must be finite, got {pnl_raw!r}"
                )

            normalized_trade["pnl"] = pnl_value

            if not await self._cb_can_execute():
                await self._repo_mark_skipped(resolved_trade_id)
                self._loop_metrics.total_skipped += 1
                self._stats["skipped_due_to_cb"] = (
                    self._stats.get("skipped_due_to_cb", 0) + 1
                )
                return {
                    "success": False,
                    "skipped": True,
                    "trade_id": resolved_trade_id,
                    "attempts": 0,
                    "error": "Circuit breaker is open",
                }

            while attempt_number < self._max_retries:
                attempt_number += 1
                process_start = time.time()

                try:
                    trade_metadata = {
                        "regime": normalized_trade.get("regime", "NORMAL"),
                        "market_context": normalized_trade.get(
                            "market_context", {}
                        ),
                        "decision_context": normalized_trade.get(
                            "decision_context", {}
                        ),
                        "attempt": attempt_number,
                        # ✅ FIXED: trade_id در metadata
                        "trade_id": resolved_trade_id,
                    }

                    # ✅ FIXED: عبور صریح trade_id به process_trade_result
                    result = self.process_trade_result(
                        strategies_used=normalized_trade["strategies_used"],
                        pnl=normalized_trade["pnl"],
                        is_profitable=normalized_trade["pnl"] > 0.0,
                        symbol=normalized_trade["symbol"],
                        trade_metadata=trade_metadata,
                        trade_id=resolved_trade_id,
                    )

                    failed_results = [
                        strategy_name
                        for strategy_name, strategy_result in result.items()
                        if not isinstance(strategy_result, dict)
                        or strategy_result.get("status") != "UPDATED"
                    ]

                    if not result:
                        raise RuntimeError(
                            "process_trade_result returned an empty result"
                        )

                    if failed_results:
                        raise RuntimeError(
                            "Failed strategy updates: "
                            + ", ".join(failed_results)
                        )

                    process_time_ms = (
                        time.time() - process_start
                    ) * 1000.0

                    await self._repo_mark_processed(resolved_trade_id)

                    async with self._state_lock:
                        self._processed_trades.add(resolved_trade_id)

                        position_id = normalized_trade.get("position_id")
                        if position_id is not None:
                            try:
                                normalized_position_id = int(position_id)
                            except (TypeError, ValueError):
                                normalized_position_id = 0

                            if normalized_position_id > 0:
                                self._processed_positions.add(
                                    normalized_position_id
                                )

                    self._loop_metrics.total_processed += 1
                    self._loop_metrics.last_processed_timestamp = datetime.now()

                    processed_count = self._loop_metrics.total_processed
                    old_average = (
                        self._loop_metrics.processing_latency_avg_ms
                    )
                    self._loop_metrics.processing_latency_avg_ms = (
                        old_average * (processed_count - 1)
                        + process_time_ms
                    ) / processed_count
                    self._loop_metrics.processing_latency_max_ms = max(
                        self._loop_metrics.processing_latency_max_ms,
                        process_time_ms,
                    )

                    await self._cb_record_success()

                    return {
                        "success": True,
                        "skipped": False,
                        "trade_id": resolved_trade_id,
                        "attempts": attempt_number,
                        "strategies_updated": len(result),
                        "latency_ms": process_time_ms,
                        "error": None,
                    }

                except asyncio.CancelledError:
                    raise
                except Exception as exc:
                    last_error = str(exc)
                    logger.warning(
                        "[%s] Attempt %d/%d failed: %s",
                        phase,
                        attempt_number,
                        self._max_retries,
                        last_error,
                        exc_info=True,
                    )

                    if attempt_number < self._max_retries:
                        backoff_seconds = min(
                            2 ** (attempt_number - 1), 30
                        )
                        await asyncio.sleep(backoff_seconds)

            await self._repo_mark_failed(
                resolved_trade_id,
                last_error or "Unknown processing failure",
            )
            self._loop_metrics.total_failed += 1
            await self._cb_record_failure()

            return {
                "success": False,
                "skipped": False,
                "trade_id": resolved_trade_id,
                "attempts": attempt_number,
                "error": last_error or "Unknown processing failure",
            }

        except asyncio.CancelledError:
            await self._repo_mark_failed(
                trade_id, "Processing task was cancelled"
            )
            raise
        except Exception as exc:
            last_error = str(exc)
            logger.error(
                "[%s] Critical processing error: %s",
                phase,
                last_error,
                exc_info=True,
            )

            await self._repo_mark_failed(
                trade_id, f"Critical error: {last_error}"
            )
            self._loop_metrics.total_failed += 1
            await self._cb_record_failure()

            return {
                "success": False,
                "skipped": False,
                "trade_id": trade_id,
                "attempts": attempt_number,
                "error": last_error,
            }
        finally:
            elapsed_ms = (time.time() - start_time) * 1000.0
            logger.debug("[%s] Finished in %.1f ms", phase, elapsed_ms)
            
    def generate_restart_safety_report(self) -> str:
        """
        ✅ FIXED V2:
          • حذف `self._strategy_weights` ناموجود — از MDE یا PM خوانده می‌شود.
          • تمام خطوط با پدینگ دقیق 62 کاراکتر + ║ پایانی.
          • محافظت کامل با try/except برای هر بخش.
        """
        phase = "RESTART_SAFETY_V2"
        try:
            # ─── Resolve strategy weights (MDE → PM → empty) ─────────────
            strategy_weights: Dict[str, float] = {}
            try:
                if getattr(self, "_mde", None) is not None and hasattr(
                    self._mde, "get_weights"
                ):
                    strategy_weights = dict(self._mde.get_weights() or {})
                elif (
                    getattr(self, "_penalty_manager", None) is not None
                    and hasattr(self._penalty_manager, "get_all_metadata")
                ):
                    pm_meta = self._penalty_manager.get_all_metadata() or {}
                    strategy_weights = {name: 1.0 for name in pm_meta}
            except Exception as w_err:
                logger.debug(f"[{phase}] weight resolve failed: {w_err}")
                strategy_weights = {}

            total_weight = sum(strategy_weights.values()) if strategy_weights else 0.0
            avg_weight = (
                total_weight / len(strategy_weights)
                if strategy_weights else 0.0
            )

            # ─── Gather state ─────────────────────────────────────────────
            processed_count = len(self._processed_trades)
            positions_count = len(self._processed_positions)
            loop_status = "RUNNING" if self._loop_running else "STOPPED"

            buffer_total = 0
            try:
                if getattr(self, "_engine", None):
                    for _name, strat in getattr(
                        self._engine, "strategy_instances", {}
                    ).items():
                        if hasattr(strat, "_learning_buffer"):
                            buffer_total += len(strat._learning_buffer)
            except Exception:
                buffer_total = 0

            cb_state = getattr(self, "_cb_state", None)
            cb_state_str = (
                cb_state.name if hasattr(cb_state, "name") else "UNKNOWN"
            )
            is_healthy = bool(self.is_healthy)

            # ─── Build report (width = 64 total, content = 62) ───────────
            line = "═" * 62
            dash = "─" * 62

            def _row(label: str, value: str) -> str:
                """یک ردیف با پدینگ دقیق به عرض 62 کاراکتر."""
                inner = f" {label}: {value}"
                if len(inner) > 62:
                    inner = inner[:59] + "..."
                return f"║{inner:<62}║"

            def _section(title: str) -> str:
                inner = f" {title}"
                return f"║{inner:<62}║"

            report_type = (
                "PRE-SHUTDOWN" if self._loop_running else "POST-STARTUP"
            )

            lines: List[str] = []
            lines.append("╔" + line + "╗")
            lines.append(
                "║" + " 🔄 RESTART SAFETY CHECKPOINT".center(62) + "║"
            )
            lines.append("╠" + line + "╣")
            lines.append(_row("⏰ Timestamp", datetime.now().strftime("%Y-%m-%d %H:%M:%S")))
            lines.append(_row("📊 Report Type", report_type))
            lines.append("╠" + dash + "╣")
            lines.append(_section("📈 LEARNING STATE"))
            lines.append(_row("Processed Trades", str(processed_count)))
            lines.append(_row("Processed Positions", str(positions_count)))
            lines.append(_row("Learning Loop", loop_status))
            lines.append(_row("Pending in Buffers", str(buffer_total)))
            if buffer_total > 0:
                lines.append(
                    "║" + f" ⚠️ {buffer_total} records not yet saved to DB!".ljust(62) + "║"
                )
            lines.append("╠" + dash + "╣")
            lines.append(_section("⚖️ WEIGHTS & PENALTIES"))
            lines.append(_row("Total Strategies", str(len(strategy_weights))))
            lines.append(_row("Avg Weight", f"{avg_weight:.3f}"))
            lines.append(_row("Circuit Breaker", cb_state_str))
            lines.append("╠" + dash + "╣")
            lines.append(_section("🏥 SYSTEM HEALTH"))
            lines.append(
                _row("Status", "✅ HEALTHY" if is_healthy else "❌ UNHEALTHY")
            )
            if (
                hasattr(self, "_loop_last_success_time")
                and self._loop_last_success_time
            ):
                try:
                    minutes_ago = (
                        datetime.now() - self._loop_last_success_time
                    ).total_seconds() / 60.0
                    lines.append(
                        _row("Last Success", f"{minutes_ago:.1f} min ago")
                    )
                except Exception:
                    pass
            lines.append("╚" + line + "╝")

            report = "\n".join(lines)

            # ─── Save to disk ────────────────────────────────────────────
            try:
                report_dir = self._base_dir / "reports" / "restart_safety"
                report_dir.mkdir(parents=True, exist_ok=True)
                timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
                report_type_file = (
                    "pre_shutdown" if self._loop_running else "post_startup"
                )
                report_file = (
                    report_dir
                    / f"restart_{report_type_file}_{timestamp}.txt"
                )
                with open(report_file, "w", encoding="utf-8") as f:
                    f.write(report)
                self._logger.info(
                    f"[{phase}] ✅ Report saved: {report_file.name}"
                )
            except Exception as save_err:
                self._logger.error(
                    f"[{phase}] ❌ Failed to save report: {save_err}"
                )

            return report

        except Exception as e:
            self._logger.error(
                f"[{phase}] ❌ Error: {e}", exc_info=True
            )
            return f"❌ Error: {str(e)}"
        
    async def initialize(self) -> None:
        """
        راه‌اندازی CLE.

        ✅ FIXED V10: bootstrap_unified_schema در استارتاپ اجرا می‌شود
        تا جدول‌های canonical ساخته و داده‌های legacy منتقل شوند.
        """
        phase = "CLE_INITIALIZE_V10"
        try:
            self._logger.info(f"[{phase}] 🚀 Initializing CLE...")

            # ─── 1. Bootstrap unified schema ────────────────────────
            try:
                db_path = Path(
                    self._config.get(
                        "db_path", "TRADE/strategy_stats.db"
                    )
                )
                bootstrap_stats = await bootstrap_unified_schema(
                    db_path=db_path,
                    drop_legacy_table=bool(
                        self._config.get(
                            "drop_legacy_strategy_signals", False
                        )
                    ),
                )
                self._logger.info(
                    f"[{phase}] ✅ Unified schema bootstrap: "
                    f"{bootstrap_stats}"
                )
            except Exception as boot_err:
                # خطای bootstrap نباید مانع ادامهٔ CLE شود
                self._logger.error(
                    f"[{phase}] ❌ Bootstrap failed: {boot_err}",
                    exc_info=True,
                )

            # ─── 2. Start performance tracker ──────────────────────
            await self._performance_tracker.start()

            # ─── 3. Load processed state ───────────────────────────
            await self._load_processed_trades()
            await self._load_processed_positions()

            # ─── 4. Register all strategies ────────────────────────
            if (
                self._penalty_manager
                and hasattr(
                    self._penalty_manager, "register_all_strategies"
                )
            ):
                if hasattr(self, "_engine") and self._engine:
                    strategy_instances = {}
                    if hasattr(self._engine, "strategy_instances"):
                        strategy_instances = (
                            self._engine.strategy_instances
                        )
                    elif hasattr(self._engine, "strategies"):
                        strategy_instances = self._engine.strategies

                    if strategy_instances:
                        self._penalty_manager.register_all_strategies(
                            strategy_instances
                        )
                        logger.info(
                            "✅ All strategies registered with "
                            "PenaltyManager"
                        )

            # ─── 5. Mark running + background tasks ───────────────
            self._running = True
            self._background_tasks.append(
                asyncio.create_task(self._background_save_task())
            )

            if self._auto_start_loop:
                self.start_loop()

            self._logger.info(
                f"CLE V{CLE_ENGINE_VERSION} initialized successfully. "
                f"Processed trades: {len(self._processed_trades)}"
            )

        except Exception as e:
            self._logger.error(
                f"[{phase}] ❌ Initialization failed: {e}",
                exc_info=True,
            )
            raise
            
    async def _learning_loop(self) -> None:
        """
        ✅ FIXED: اضافه کردن فراخوانی generate_comprehensive_diagnostic_report در حلقه یادگیری
        ✅ FIXED: هر ۱۰ سیکل یک بار گزارش تشخیصی کامل تولید می‌شود
        """
        phase = "CLE_LEARNING_LOOP_V3"
        optimization_cycle = 0
        optimization_interval = 10  # هر 10 سیکل یک بار بهینه‌سازی
        diagnostic_cycle = 0
        diagnostic_interval = 10  # هر 10 سیکل یک بار گزارش تشخیصی
        try:
            logger.info(f"[{phase}] 🚀 Starting learning loop with retry mechanism")
            while self._loop_running:
                try:
                    # PHASE 1: Process Trades
                    await self._process_pending_trades()
                    
                    # PHASE 2: Update Weights
                    await self._update_strategy_weights()
                    
                    # ✅ NEW PHASE 2.5: Optimize Parameters (هر 10 سیکل)
                    optimization_cycle += 1
                    if optimization_cycle >= optimization_interval:
                        optimization_cycle = 0
                        await self._optimize_all_parameters()
                    
                    # ✅ NEW PHASE 2.6: Generate Comprehensive Diagnostic Report (هر 10 سیکل)
                    diagnostic_cycle += 1
                    if diagnostic_cycle >= diagnostic_interval:
                        diagnostic_cycle = 0
                        await self._generate_comprehensive_diagnostic()
                    
                    # PHASE 3: Generate Report
                    await self._generate_periodic_report()
                    
                    # PHASE 4: Success Tracking
                    self._loop_consecutive_failures = 0
                    self._loop_last_success_time = datetime.now()
                    if self._degradation_mode_active:
                        self._degradation_mode_active = False
                        self._degradation_mode_start_time = None
                        logger.info(f"[{phase}] 🔓 Degradation mode deactivated")
                    
                    # PHASE 5: Wait for Next Cycle
                    await asyncio.sleep(self._interval_seconds)
                    
                except asyncio.CancelledError:
                    logger.info(f"[{phase}] 🛑 Learning loop cancelled")
                    break
                except Exception as e:
                    self._loop_consecutive_failures += 1
                    logger.error(
                        f"[{phase}] ❌ Learning loop error (failure #{self._loop_consecutive_failures}): {e}",
                        exc_info=True
                    )
                    if self._loop_consecutive_failures >= self._loop_max_consecutive_failures:
                        if not self._degradation_mode_active:
                            self._degradation_mode_active = True
                            self._degradation_mode_start_time = datetime.now()
                            logger.critical(
                                f"[{phase}] 🔒 Entering degradation mode after "
                                f"{self._loop_consecutive_failures} consecutive failures"
                            )
                    if self._loop_retry_count < self._loop_max_retries:
                        backoff_delay = min(
                            self._loop_retry_backoff_base ** self._loop_retry_count,
                            self._loop_retry_max_delay
                        )
                        logger.warning(
                            f"[{phase}] ⏳ Retrying in {backoff_delay}s "
                            f"(retry #{self._loop_retry_count + 1}/{self._loop_max_retries})"
                        )
                        await asyncio.sleep(backoff_delay)
                        self._loop_retry_count += 1
                    else:
                        logger.critical(
                            f"[{phase}] 🔴 Max retries reached "
                            f"({self._loop_max_retries}), entering permanent degradation mode"
                        )
                        await asyncio.sleep(self._loop_retry_max_delay)
                        self._loop_retry_count = 0
            
            logger.info(f"[{phase}] 🛑 Learning loop stopped")
        except Exception as e:
            logger.error(f"[{phase}] ❌ Fatal error in learning loop: {e}", exc_info=True)
            self._loop_running = False
        
    async def _optimize_all_parameters(self) -> None:
        """
        ✅ NEW: بهینه‌سازی پارامترهای همه استراتژی‌ها
        فراخوانی شده در حلقه یادگیری هر 10 سیکل
        """
        phase = "OPTIMIZE_ALL_PARAMETERS"
        try:
            if not self._penalty_manager:
                logger.debug(f"[{phase}] PenaltyManager not available")
                return
            
            if not hasattr(self._penalty_manager, 'optimize_all_strategies'):
                logger.warning(f"[{phase}] PenaltyManager does not have optimize_all_strategies method")
                return
            
            # فراخوانی بهینه‌سازی همه استراتژی‌ها
            results = self._penalty_manager.optimize_all_strategies()
            
            if results:
                logger.info(f"[{phase}] ✅ Optimized {len(results)} strategies")
                for strategy_name, params in results.items():
                    logger.debug(f"[{phase}] {strategy_name}: {params}")
            else:
                logger.debug(f"[{phase}] No strategies needed optimization")
                
        except Exception as e:
            logger.error(f"[{phase}] ❌ Error: {e}", exc_info=True)
            
    async def shutdown(self) -> None:
        self._running = False

        for task in self._background_tasks:
            task.cancel()
        if self._background_tasks:
            try:
                await asyncio.gather(*self._background_tasks, return_exceptions=True)
            except Exception:
                pass

        if self._loop_running:
            await self.stop_loop()

        await self._performance_tracker.stop()
        await self._save_processed_trades()
        await self._save_processed_positions()
        self._logger.info("CLE V8.0 shut down")

    def start(self) -> None:
        """Alias برای start_loop()."""
        self.start_loop()

    async def stop(self, timeout_seconds: int = 60) -> None:
        """Alias برای stop_loop()."""
        await self.stop_loop(timeout_seconds=timeout_seconds)


    def set_mde(self, mde: Any) -> None:
        if not hasattr(mde, 'get_weights') or not hasattr(mde, 'set_weights'):
            raise ValueError("MDE must implement get_weights() and set_weights()")
        self._mde = mde
        self._weight_optimizer = WeightOptimizer(
            mde=mde,
            learning_rate=self._learning_rate,
            min_weight=self._min_weight,
            max_weight=self._max_weight,
        )
        self._logger.info("MDE connected to CLE")

    def set_penalty_manager(self, penalty_manager: Any) -> None:
        self._penalty_manager = penalty_manager
        self._logger.info("PenaltyManager connected to CLE")

    def set_signal_file_manager(self, sfm: Any) -> None:
        self._signal_file_manager = sfm
        self._logger.info("SignalFileManager connected to CLE")

    # ========================================================================
    # SECTION 1.5: PROCESSED POSITIONS TRACKING (✅ FIXED: Missing Methods)
    # ========================================================================

    async def _is_position_processed(self, position_id: int) -> bool:
        """
        ✅ NEW: Check if a position_id has already been processed.
        Thread-safe via _state_lock.
        Returns False on any error (fail-open to avoid blocking learning).

        Args:
            position_id: The MT5 position ticket number.

        Returns:
            bool: True if already processed, False otherwise.
        """
        try:
            async with self._state_lock:
                return position_id in self._processed_positions
        except Exception as e:
            self._logger.error(
                f"[_is_position_processed] Error checking position {position_id}: {e}",
                exc_info=True
            )
            return False

    async def _load_processed_positions(self) -> None:
        """
        ✅ NEW: Load processed position IDs from disk (JSON).
        Called once during initialize().
        Uses AtomicFileStore for crash-safe reads.
        """
        phase = "LOAD_PROCESSED_POSITIONS"
        try:
            if not self._position_cache_file.exists():
                self._logger.info(
                    f"[{phase}] ℹ️ No processed positions file found. Starting fresh."
                )
                return

            async with self._store.atomic_read(
                self._position_cache_file, default={}
            ) as data:
                if data and isinstance(data, dict):
                    positions = data.get('positions', [])
                    if isinstance(positions, list):
                        async with self._state_lock:
                            self._processed_positions = set(
                                int(p) for p in positions if isinstance(p, (int, float))
                            )
                        self._logger.info(
                            f"[{phase}] ✅ Loaded {len(self._processed_positions)} "
                            f"processed positions from disk"
                        )
                    else:
                        self._logger.warning(
                            f"[{phase}] ⚠️ Invalid positions format in cache file"
                        )
                else:
                    self._logger.info(
                        f"[{phase}] ℹ️ Empty or invalid cache file"
                    )
        except Exception as e:
            self._logger.warning(
                f"[{phase}] ⚠️ Failed to load processed positions: {e}"
            )

    async def _save_processed_positions(self) -> None:
        """
        ✅ NEW: Save processed position IDs to disk (JSON).
        Called during shutdown() and periodically.
        Uses AtomicFileStore for crash-safe atomic writes.
        Keeps only the last 50,000 entries to prevent unbounded growth.
        """
        phase = "SAVE_PROCESSED_POSITIONS"
        try:
            async with self._state_lock:
                # ✅ Prevent unbounded memory growth
                if len(self._processed_positions) > 50_000:
                    sorted_positions = sorted(self._processed_positions)
                    self._processed_positions = set(sorted_positions[-50_000:])
                    self._logger.info(
                        f"[{phase}] 🗑️ Trimmed positions to 50,000 entries"
                    )
                positions_list = list(self._processed_positions)

            data = {
                'positions': positions_list,
                'count': len(positions_list),
                'timestamp': datetime.now().isoformat(),
                'version': CLE_DATA_VERSION
            }

            async with self._store.atomic_write(self._position_cache_file, data):
                pass

            self._logger.debug(
                f"[{phase}] ✅ Saved {len(positions_list)} processed positions"
            )
        except Exception as e:
            self._logger.error(
                f"[{phase}] ❌ Failed to save processed positions: {e}",
                exc_info=True
            )

    def reset_paralyzed_strategies(self, min_hours: int = 24) -> int:
        """
        بازنشانی penalty استراتژی‌هایی که برای مدت طولانی مسدود بوده‌اند.

        ✅ FIXED V2: به‌جای دسترسی مستقیم به `self.strategy_metadata`
        (که در CLE تعریف نشده)، به PenaltyManager یا SignalFileManager
        delegate می‌شود.
        """
        phase = "RESET_PARALYZED_STRATEGIES"
        reset_count = 0

        # ─── 1. تلاش برای استفاده از PenaltyManager ──────────────────
        if (
            self._penalty_manager is not None
            and hasattr(self._penalty_manager, "reset_strategy")
            and hasattr(self._penalty_manager, "get_all_metadata")
        ):
            try:
                now = datetime.now()
                reset_count = 0
                for name, meta in self._penalty_manager.get_all_metadata().items():
                    last_trade = getattr(meta, "last_trade_time", None)
                    if last_trade is None:
                        continue
                    idle_hours = (now - last_trade).total_seconds() / 3600.0
                    if idle_hours >= float(min_hours):
                        if self._penalty_manager.reset_strategy(name):
                            reset_count += 1
                logger.info(
                    f"[{phase}] ✅ PenaltyManager reset "
                    f"{reset_count} idle strategies (idle≥{min_hours}h)"
                )
                return reset_count
            except Exception as e:
                logger.error(
                    f"[{phase}] ❌ PenaltyManager reset failed: {e}",
                    exc_info=True,
                )
                
        # ─── 2. Fallback: از SignalFileManager ──────────────────────
        if (
            self._signal_file_manager is not None
            and hasattr(
                self._signal_file_manager, "reset_paralyzed_strategies"
            )
        ):
            try:
                reset_count = (
                    self._signal_file_manager.reset_paralyzed_strategies(
                        min_hours=min_hours
                    )
                )
                logger.info(
                    f"[{phase}] ✅ SignalFileManager reset "
                    f"{reset_count} strategies"
                )
                return reset_count
            except Exception as e:
                logger.error(
                    f"[{phase}] ❌ SignalFileManager reset failed: {e}",
                    exc_info=True,
                )

        # ─── 3. هیچ منبعی در دسترس نیست ──────────────────────────────
        logger.warning(
            f"[{phase}] ⚠️ No reset-capable manager available "
            f"(PenaltyManager or SignalFileManager); skipping."
        )
        return 0
        

    def process_trade_result(
        self,
        symbol: str = "DEFAULT",
        strategy: Optional[str] = None,
        pnl: float = 0.0,
        win: Optional[bool] = None,
        hold_duration: float = 0.0,
        regime: Optional[str] = None,
        strategies_used: Optional[List[str]] = None,
        is_profitable: Optional[bool] = None,
        trade_metadata: Optional[Dict[str, Any]] = None,
        trade_id: Optional[str] = None,
        **kwargs: Any,
    ) -> Dict[str, Any]:
        """
        ╔══════════════════════════════════════════════════════════════════════════╗
        ║  PROCESS TRADE RESULT — V12 (SSOT-FAITHFUL: status reflects reality)    ║
        ║  ✅ FIX P0: status = "UPDATED" ONLY if penalty_updated == True           ║
        ║     در غیر این صورت "FAILED" ست می‌شود تا `_process_trade_with_retry`    ║
        ║     بتواند retry کند.                                                     ║
        ╚══════════════════════════════════════════════════════════════════════════╝
        """
        try:
            # ─── Validation ────────────────────────────────────────────────
            try:
                pnl_value = float(pnl)
            except (TypeError, ValueError) as exc:
                raise ValueError(f"pnl must be numeric, got {pnl!r}") from exc

            if not math.isfinite(pnl_value):
                raise ValueError(f"pnl must be finite, got {pnl!r}")

            symbol_value = str(symbol or "DEFAULT").strip().upper()
            if not symbol_value:
                symbol_value = "DEFAULT"

            metadata = dict(trade_metadata or {})

            # ─── Resolve trade_id / signal_id ─────────────────────────────
            resolved_trade_id = (
                trade_id
                or metadata.get("trade_id")
                or metadata.get("id")
                or kwargs.get("trade_id")
                or kwargs.get("id")
            )
            if resolved_trade_id is not None:
                resolved_trade_id = str(resolved_trade_id)
            else:
                resolved_trade_id = f"TRADE_{uuid.uuid4().hex}"

            resolved_signal_id = str(
                metadata.get("signal_id") or resolved_trade_id
            )

            regime_value = str(
                regime
                or metadata.get("regime")
                or metadata.get("market_regime")
                or kwargs.get("market_regime")
                or "NEUTRAL"
            )

            profitable_value = (
                bool(is_profitable)
                if is_profitable is not None
                else bool(win)
                if win is not None
                else pnl_value > 0.0
            )

            # ─── Collect strategies ────────────────────────────────────────
            strategy_names: List[str] = []

            if strategies_used:
                for name in strategies_used:
                    normalized_name = str(name or "").strip()
                    if normalized_name and normalized_name not in strategy_names:
                        strategy_names.append(normalized_name)

            if strategy:
                normalized_strategy = str(strategy).strip()
                if normalized_strategy and normalized_strategy not in strategy_names:
                    strategy_names.append(normalized_strategy)

            if not strategy_names:
                raise ValueError(
                    "At least one strategy must be supplied through "
                    "strategy or strategies_used"
                )

            # ─── History ───────────────────────────────────────────────────
            if not hasattr(self, "trade_history") or not isinstance(
                self.trade_history, list
            ):
                self.trade_history = []

            _MAX_HISTORY = int(self._config.get("trade_history_limit", 500))
            if _MAX_HISTORY > 0 and len(self.trade_history) > _MAX_HISTORY:
                self.trade_history = self.trade_history[-_MAX_HISTORY:]

            timestamp = datetime.now()
            result: Dict[str, Any] = {}

            # ─── Process each strategy ─────────────────────────────────────
            sfm = getattr(self, "_signal_file_manager", None)
            pm = getattr(self, "_penalty_manager", None)

            for strategy_name in strategy_names:
                record = {
                    "timestamp": timestamp,
                    "symbol": symbol_value,
                    "strategy": strategy_name,
                    "pnl": pnl_value,
                    "win": profitable_value,
                    "hold_duration": float(hold_duration),
                    "regime": regime_value,
                    "trade_metadata": metadata,
                    "trade_id": resolved_trade_id,
                }

                self.trade_history.append(record)
                if len(self.trade_history) > self._TRADES_HISTORY_MAX:
                    self.trade_history = self.trade_history[-self._TRADES_HISTORY_MAX:]

                # ─── Single funnel: SFM → PM → DB ─────────────────────
                penalty_updated = False
                funnel_used = "none"

                if sfm is not None and hasattr(sfm, "update_strategy_performance"):
                    try:
                        sfm_success = sfm.update_strategy_performance(
                            strategy_name=strategy_name,
                            is_profitable=profitable_value,
                            pnl=pnl_value,
                            symbol=symbol_value,
                            trade=metadata if isinstance(metadata, dict) else None,
                            trade_id=resolved_trade_id,
                            signal_id=resolved_signal_id,
                        )
                        penalty_updated = bool(sfm_success)
                        funnel_used = "sfm"
                    except Exception as sfm_err:
                        logger.warning(
                            f"[process_trade_result] SFM update failed for "
                            f"{strategy_name}: {sfm_err}"
                        )
                        penalty_updated = False

                # ─── Fallback: direct PM (only if SFM failed) ──────────
                if not penalty_updated and pm is not None and hasattr(
                    pm, "update_performance"
                ):
                    try:
                        pm_result = pm.update_performance(
                            strategy=strategy_name,
                            is_profitable=profitable_value,
                            pnl=pnl_value,
                            symbol=symbol_value,
                            trade_id=resolved_trade_id,
                            signal_id=resolved_signal_id,
                        )
                        penalty_updated = pm_result is not None
                        if penalty_updated:
                            funnel_used = "pm_fallback"
                    except Exception as pen_err:
                        logger.warning(
                            f"[process_trade_result] PM fallback failed for "
                            f"{strategy_name}: {pen_err}"
                        )
                        penalty_updated = False

                # ✅ FIX P0: status reflects reality
                status_value = "UPDATED" if penalty_updated else "FAILED"
                if not penalty_updated:
                    logger.warning(
                        f"[process_trade_result] ⚠️ Strategy '{strategy_name}' "
                        f"update FAILED (no SFM, no PM, or both errored). "
                        f"Marking status=FAILED to trigger retry."
                    )

                result[strategy_name] = {
                    "status": status_value,
                    "strategy": strategy_name,
                    "symbol": symbol_value,
                    "pnl": pnl_value,
                    "is_profitable": profitable_value,
                    "regime": regime_value,
                    "trade_id": resolved_trade_id,
                    "penalty_updated": penalty_updated,
                    "funnel_used": funnel_used,
                }

                # ─── Performance Tracker (fire-and-forget) ────────────
                try:
                    outcome = TradeOutcome.from_pnl_safe(pnl_value)

                    try:
                        loop = asyncio.get_running_loop()
                        loop.create_task(
                            self._performance_tracker.update_strategy(
                                strategy_name=strategy_name,
                                symbol=symbol_value,
                                pnl=pnl_value,
                                outcome=outcome,
                            )
                        )
                    except RuntimeError:
                        import concurrent.futures
                        with concurrent.futures.ThreadPoolExecutor(
                            max_workers=1
                        ) as ex:
                            future = ex.submit(
                                lambda: asyncio.run(
                                    self._performance_tracker.update_strategy(
                                        strategy_name=strategy_name,
                                        symbol=symbol_value,
                                        pnl=pnl_value,
                                        outcome=outcome,
                                    )
                                )
                            )
                            future.result(timeout=5.0)

                except Exception as tracker_err:
                    logger.debug(
                        f"[process_trade_result] tracker update failed for "
                        f"{strategy_name}: {tracker_err}"
                    )

            self._processed_count += 1
            return result

        except Exception as e:
            logger.error(
                f"[process_trade_result] ❌ Error: {e}", exc_info=True
            )
            return {}
        
    async def _load_processed_trades(self) -> None:
        """
        Load processed trades from SQLite database.

        ✅ FIXED: Schema کاملاً با `_is_trade_processed_db` یکسان شد
        (افزودن ستون‌های `pnl` و `outcome`) تا هر دو مسیر با یک جدول
        کار کنند.
        """
        phase = "LOAD_PROCESSED_TRADES_DB"

        try:
            db_path = Path(
                self._config.get("db_path", "TRADE/strategy_stats.db")
            )
            db_path.parent.mkdir(parents=True, exist_ok=True)

            with sqlite3.connect(str(db_path)) as conn:
                cursor = conn.cursor()

                # ─── ✅ Unified schema (مطابق _is_trade_processed_db) ───
                cursor.execute("""
                    CREATE TABLE IF NOT EXISTS processed_trades (
                        trade_id TEXT PRIMARY KEY,
                        processed_at TEXT NOT NULL,
                        symbol TEXT NOT NULL,
                        strategies_used TEXT,
                        pnl REAL DEFAULT 0.0,
                        outcome TEXT DEFAULT 'UNKNOWN'
                    )
                """)
                conn.commit()

                cursor.execute("SELECT trade_id FROM processed_trades")
                rows = cursor.fetchall()

                async with self._state_lock:
                    self._processed_trades = {row[0] for row in rows}
                    self._processed_count = len(self._processed_trades)

                self._logger.info(
                    f"[{phase}] ✅ Loaded {len(self._processed_trades)} "
                    f"processed trades from database"
                )

        except Exception as e:
            self._logger.warning(
                f"[{phase}] ⚠️ Failed to load from DB: {e}. "
                f"Falling back to file."
            )
            await self._load_processed_trades_file()
        
    async def _is_trade_processed_db(self, trade_id: str) -> bool:
        """
        وجود شناسه معامله را در حافظه و SQLite بررسی می‌کند.

        ✅ FIXED: Schema با `_load_processed_trades` همسان شد.
        """
        normalized_id = str(trade_id or "").strip()
        if not normalized_id:
            return False

        async with self._state_lock:
            if normalized_id in self._processed_trades:
                return True

        db_path = Path(
            self._config.get("db_path", "TRADE/strategy_stats.db")
        )

        if not db_path.exists():
            return False

        def check_database() -> bool:
            with sqlite3.connect(str(db_path), timeout=10.0) as conn:
                conn.execute(
                    """
                    CREATE TABLE IF NOT EXISTS processed_trades (
                        trade_id TEXT PRIMARY KEY,
                        processed_at TEXT NOT NULL,
                        symbol TEXT NOT NULL,
                        strategies_used TEXT,
                        pnl REAL DEFAULT 0.0,
                        outcome TEXT DEFAULT 'UNKNOWN'
                    )
                    """
                )
                row = conn.execute(
                    "SELECT 1 FROM processed_trades WHERE trade_id = ?",
                    (normalized_id,),
                ).fetchone()
                return row is not None

        try:
            return await asyncio.to_thread(check_database)
        except (sqlite3.Error, OSError) as exc:
            self._logger.warning(
                "Database processed-trade lookup failed for %s: %s",
                normalized_id,
                exc,
            )
            async with self._state_lock:
                return normalized_id in self._processed_trades
                
    async def _load_processed_trades_file(self) -> None:
        """
        Fallback method to load from JSON file (legacy)
        """
        try:
            file_path = self._processed_file
            if file_path.exists():
                async with self._store.atomic_read(file_path, default={}) as data:
                    if data:
                        trades = data.get('trades', [])
                        async with self._state_lock:
                            self._processed_trades = set(trades)
                            self._processed_count = len(self._processed_trades)
                        self._logger.info(f"✅ Loaded {len(self._processed_trades)} processed trades from file (fallback)")
        except Exception as e:
            self._logger.warning(f"⚠️ Failed to load processed trades from file: {e}")

    async def _save_processed_trades(self) -> None:
        """
        ✅ FIXED: Save processed trades to SQLite database with atomic write
        و Fallback به فایل در صورت خطا
        """
        phase = "SAVE_PROCESSED_TRADES_DB"
        
        try:
            import sqlite3
            from datetime import datetime
            
            # ─── 1. گرفتن snapshot از داده‌ها ──────────────────────────────────
            async with self._state_lock:
                trades_to_save = list(self._processed_trades)
                count = len(trades_to_save)
            
            if count == 0:
                logger.debug(f"[{phase}] ℹ️ No trades to save")
                return
            
            # ─── 2. اطمینان از وجود دایرکتوری ──────────────────────────────────
            db_path = Path(self._config.get('db_path', 'TRADE/strategy_stats.db'))
            db_path.parent.mkdir(parents=True, exist_ok=True)
            
            # ─── 3. ذخیره در دیتابیس ──────────────────────────────────────────
            with sqlite3.connect(str(db_path)) as conn:
                cursor = conn.cursor()
                
                # ایجاد جدول اگر وجود ندارد
                cursor.execute("""
                    CREATE TABLE IF NOT EXISTS processed_trades (
                        trade_id TEXT PRIMARY KEY,
                        processed_at TEXT NOT NULL,
                        symbol TEXT NOT NULL,
                        strategies_used TEXT,
                        pnl REAL DEFAULT 0.0,
                        outcome TEXT DEFAULT 'UNKNOWN'
                    )
                """)
                
                # ذخیره به صورت batch
                now = datetime.now().isoformat()
                batch_size = 100
                
                for i in range(0, len(trades_to_save), batch_size):
                    batch = trades_to_save[i:i+batch_size]
                    for trade_id in batch:
                        cursor.execute("""
                            INSERT OR REPLACE INTO processed_trades 
                            (trade_id, processed_at, symbol, strategies_used)
                            VALUES (?, ?, ?, ?)
                        """, (trade_id, now, 'UNKNOWN', '[]'))
                
                conn.commit()
            try:
                self.clear_cache()
            except Exception:
                pass
            logger.info(f"[{phase}] ✅ Saved {count} processed trades to database")
            
        except Exception as e:
            logger.warning(f"[{phase}] ⚠️ Failed to save to database: {e}. Falling back to file.")
            # ─── 4. Fallback به فایل ──────────────────────────────────────────
            await self._save_processed_trades_file()
            
    async def _save_processed_trades_file(self) -> None:
        """
        Fallback method to save to JSON file (legacy)
        """
        try:
            async with self._state_lock:
                data = {
                    'timestamp': datetime.now().isoformat(),
                    'count': len(self._processed_trades),
                    'trades': list(self._processed_trades),
                }
            async with self._store.atomic_write(self._processed_file, data):
                pass
            logger.debug(f"[SAVE_FILE] ✅ Saved {len(data['trades'])} trades to file")
        except Exception as e:
            logger.error(f"[SAVE_FILE] ❌ Failed to save to file: {e}")
        
    async def _background_save_task(self) -> None:
        while self._running:
            try:
                await asyncio.sleep(60)
                await self._performance_tracker._save()
                await self._save_processed_trades()
                self._logger.debug("Background save completed")
            except asyncio.CancelledError:
                break
            except Exception as e:
                self._logger.warning(f"Background save error: {e}")

    # ========================================================================
    # SECTION 5: گزارش‌گیری (ساختار قبلی حفظ شده + بخش اختیاری جدید)
    # ========================================================================

    async def generate_report(self) -> Dict[str, Any]:
        try:
            report = {
                'timestamp': datetime.now().isoformat(),
                'version': CLE_ENGINE_VERSION,
                'performance': {},
                'regime_analysis': {},
                'summary': {},
            }

            total_trades = 0
            total_pnl = 0.0
            total_strategies = 0

            async with self._state_lock:
                for strategy, symbols in self._performance_tracker._stats.items():
                    report['performance'][strategy] = {}
                    for symbol, stats in symbols.items():
                        report['performance'][strategy][symbol] = {
                            'win_rate': stats.win_rate,
                            'total_trades': stats.total_trades,
                            'total_pnl': float(stats.total_pnl),
                            'avg_pnl': float(stats.avg_pnl),
                            'wins': stats.wins,
                            'losses': stats.losses,
                            'break_even': stats.break_even,
                        }
                        total_trades += stats.total_trades
                        total_pnl += stats.total_pnl
                        total_strategies += 1

            for regime, data in self._regime_performance.items():
                wins = data.get('wins', [])
                pnls = data.get('pnl', [])
                if wins:
                    report['regime_analysis'][regime] = {
                        'win_rate': sum(wins) / len(wins) if wins else 0.0,
                        'total_trades': len(wins),
                        'total_pnl': float(sum(pnls)),
                        'avg_pnl': float(sum(pnls) / len(pnls)) if pnls else 0.0,
                    }

            report['summary'] = {
                'total_strategies': len(report['performance']),
                'total_strategy_symbol_pairs': total_strategies,
                'total_trades_processed': total_trades,
                'total_pnl': float(total_pnl),
                'processed_trades': len(self._processed_trades),
                'error_count': self._error_count,
                'successful_updates': self._processed_count,
            }

            # بخش جدید (اضافه‌شده، هیچ کلید قبلی را جایگزین نمی‌کند)
            report['loop_status'] = {
                'loop_running': self._loop_running,
                'circuit_breaker_state': self._cb_state.value,
                'repository': await self._repo_get_metrics(),
            }

            return report
        except Exception as e:
            self._logger.error(f"Report generation error: {e}")
            return {'error': str(e), 'timestamp': datetime.now().isoformat()}

    @classmethod
    def _validate_and_normalize_trade(
        cls,
        trade: Dict[str, Any],
    ) -> Optional[Dict[str, Any]]:
        """
        داده خام معامله بسته‌شده را اعتبارسنجی و نرمال می‌کند.

        Returns:
            دیکشنری نرمال‌شده یا None برای ورودی غیرقابل‌پردازش.
        """
        if not isinstance(trade, dict) or not trade:
            logger.warning("Trade must be a non-empty dictionary")
            return None

        symbol = str(trade.get("symbol") or "").strip().upper()
        if not symbol:
            logger.warning("Trade is missing symbol")
            return None

        status = str(trade.get("status") or "").strip().upper()
        valid_statuses = {
            "CLOSED",
            "FILLED",
            "COMPLETED",
            "SETTLED",
        }

        if status not in valid_statuses:
            logger.debug(
                "Trade %s is not closed; status=%r",
                trade.get("trade_id") or trade.get("id"),
                status,
            )
            return None

        try:
            pnl = float(trade.get("pnl", trade.get("final_pnl", 0.0)))
        except (TypeError, ValueError):
            logger.warning(
                "Trade %s has invalid PnL",
                trade.get("trade_id") or trade.get("id"),
            )
            return None

        if not math.isfinite(pnl):
            logger.warning(
                "Trade %s has non-finite PnL",
                trade.get("trade_id") or trade.get("id"),
            )
            return None

        def safe_float(value: Any, default: float = 0.0) -> float:
            try:
                result = float(value)
            except (TypeError, ValueError):
                return default
            return result if math.isfinite(result) else default

        strategies_used = trade.get("strategies_used")

        if not isinstance(strategies_used, (list, tuple, set)):
            strategies_used = []

        normalized_strategies: List[str] = []
        for raw_name in strategies_used:
            name = str(raw_name or "").strip()
            if name and name not in normalized_strategies:
                normalized_strategies.append(name)

        if not normalized_strategies:
            strategy_details = trade.get("strategy_details", {})
            if isinstance(strategy_details, dict):
                for raw_name in strategy_details:
                    name = str(raw_name or "").strip()
                    if name and name not in normalized_strategies:
                        normalized_strategies.append(name)

        if not normalized_strategies:
            raw_strategy = str(trade.get("strategy") or "").strip()
            if raw_strategy:
                normalized_strategies.append(raw_strategy)

        if not normalized_strategies:
            logger.warning(
                "Trade %s has no attributable strategy; skipping learning",
                trade.get("trade_id") or trade.get("id"),
            )
            return None

        trade_id = str(
            trade.get("trade_id")
            or trade.get("id")
            or trade.get("signal_id")
            or uuid.uuid4()
        )

        position_id_raw = trade.get(
            "position_id",
            trade.get("order_id"),
        )
        try:
            position_id = int(position_id_raw)
        except (TypeError, ValueError):
            position_id = 0

        regime = str(
            trade.get("regime")
            or trade.get("market_regime")
            or "NORMAL"
        )

        return {
            "id": trade_id,
            "trade_id": trade_id,
            "position_id": position_id,
            "symbol": symbol,
            "pnl": pnl,
            "is_winning": pnl > 0.0,
            "status": "CLOSED",
            "strategies_used": normalized_strategies,
            "regime": regime,
            "market_context": {
                "regime": regime,
                "price": safe_float(
                    trade.get(
                        "price",
                        trade.get("exit_price", 0.0),
                    )
                ),
                "volume": safe_float(
                    trade.get(
                        "volume",
                        trade.get("lot_size", 0.0),
                    )
                ),
            },
            "decision_context": {
                "strategies_used": normalized_strategies,
                "entry_time": trade.get("entry_time"),
                "exit_time": trade.get("exit_time"),
                "entry_price": safe_float(trade.get("entry_price")),
                "exit_price": safe_float(trade.get("exit_price")),
            },
            "cle_metadata": {
                "version": CLE_DATA_VERSION,
                "processed_at": None,
                "validation_time": datetime.now().isoformat(),
            },
        }
        
    async def _repo_add(self, trade: Dict[str, Any]) -> str:
        trade_id = trade.get('id', str(uuid.uuid4()))
        trade['cle_status'] = CLE_TradeStatus.PENDING.value
        trade['cle_metadata'] = trade.get('cle_metadata', {})
        trade['cle_metadata']['added_at'] = datetime.now().isoformat()

        async with self._repo_lock:
            if len(self._trades) >= self._repo_max_size:
                await self._repo_evict_oldest()
            self._trades[trade_id] = trade
            self._id_by_status[CLE_TradeStatus.PENDING].add(trade_id)

        return trade_id

    async def _repo_get_pending(self, limit: int = CLE_MAX_BATCH_SIZE) -> List[Dict[str, Any]]:
        async with self._repo_lock:
            pending_ids = list(self._id_by_status[CLE_TradeStatus.PENDING])
            if not pending_ids:
                return []

            batch_ids = pending_ids[:limit]
            result = []
            for trade_id in batch_ids:
                if trade_id in self._trades:
                    trade = self._trades[trade_id]
                    trade['cle_status'] = CLE_TradeStatus.PROCESSING.value
                    trade['cle_metadata']['processing_started_at'] = datetime.now().isoformat()
                    self._id_by_status[CLE_TradeStatus.PENDING].discard(trade_id)
                    self._id_by_status[CLE_TradeStatus.PROCESSING].add(trade_id)
                    result.append(trade)
            return result

    async def _repo_mark_processed(self, trade_id: str) -> bool:
        async with self._repo_lock:
            if trade_id not in self._trades:
                return False
            trade = self._trades[trade_id]
            trade['cle_status'] = CLE_TradeStatus.PROCESSED.value
            trade['cle_metadata']['processed_at'] = datetime.now().isoformat()
            self._id_by_status[CLE_TradeStatus.PROCESSING].discard(trade_id)
            self._id_by_status[CLE_TradeStatus.PROCESSED].add(trade_id)
            return True

    async def _repo_mark_skipped(self, trade_id: str) -> bool:
        async with self._repo_lock:
            if trade_id not in self._trades:
                return False
            trade = self._trades[trade_id]
            trade['cle_status'] = CLE_TradeStatus.SKIPPED.value
            trade['cle_metadata']['skipped_at'] = datetime.now().isoformat()
            self._id_by_status[CLE_TradeStatus.PROCESSING].discard(trade_id)
            self._id_by_status[CLE_TradeStatus.SKIPPED].add(trade_id)
            return True

    async def _repo_mark_failed(self, trade_id: str, error: str) -> bool:
        async with self._repo_lock:
            if trade_id not in self._trades:
                return False
            trade = self._trades[trade_id]
            trade['cle_status'] = CLE_TradeStatus.FAILED.value
            trade['cle_metadata']['failure_reason'] = error
            trade['cle_metadata']['failed_at'] = datetime.now().isoformat()
            self._id_by_status[CLE_TradeStatus.PROCESSING].discard(trade_id)
            self._id_by_status[CLE_TradeStatus.FAILED].add(trade_id)
            return True

    async def _repo_evict_oldest(self) -> None:
        processed_ids = list(self._id_by_status[CLE_TradeStatus.PROCESSED])
        if processed_ids:
            sorted_ids = sorted(
                processed_ids,
                key=lambda tid: self._trades[tid].get('cle_metadata', {}).get('processed_at', ''),
            )
            evict_count = max(1, len(sorted_ids) // 10)
            for trade_id in sorted_ids[:evict_count]:
                self._trades.pop(trade_id, None)
                self._id_by_status[CLE_TradeStatus.PROCESSED].discard(trade_id)

    async def _repo_get_metrics(self) -> Dict[str, Any]:
        async with self._repo_lock:
            return {
                'total_trades': len(self._trades),
                'pending': len(self._id_by_status[CLE_TradeStatus.PENDING]),
                'processing': len(self._id_by_status[CLE_TradeStatus.PROCESSING]),
                'processed': len(self._id_by_status[CLE_TradeStatus.PROCESSED]),
                'failed': len(self._id_by_status[CLE_TradeStatus.FAILED]),
                'skipped': len(self._id_by_status[CLE_TradeStatus.SKIPPED]),
                'max_size': self._repo_max_size,
            }

    async def get_trade_by_id(self, trade_id: str) -> Optional[Dict[str, Any]]:
        async with self._repo_lock:
            return self._trades.get(trade_id)

    # ========================================================================
    # SECTION 8: مدار قطع‌کننده خطا (ادغام‌شده از CLE_CircuitBreaker)
    # ========================================================================

    async def _cb_can_execute(self) -> bool:
        async with self._cb_lock:
            if self._cb_state == CircuitBreakerState.OPEN:
                if datetime.now() - self._cb_state_changed_at > timedelta(seconds=self._cb_timeout_seconds):
                    self._cb_state = CircuitBreakerState.HALF_OPEN
                    self._cb_state_changed_at = datetime.now()
                    self._logger.info("Circuit breaker moved from OPEN to HALF_OPEN")
                    return True
                return False
            return True

    async def _cb_record_success(self) -> None:
        async with self._cb_lock:
            if self._cb_state == CircuitBreakerState.HALF_OPEN:
                self._cb_reset_locked()

    async def _cb_record_failure(self) -> None:
        """تنها نقطه‌ای که مدار را باز می‌کند تا شمارنده‌ها ناسازگار نشوند."""
        async with self._cb_lock:
            if self._cb_state in (CircuitBreakerState.CLOSED, CircuitBreakerState.HALF_OPEN):
                self._cb_failure_count += 1
                if self._cb_failure_count >= self._cb_failure_threshold:
                    self._cb_open_locked()

    def _cb_open_locked(self) -> None:
        self._cb_state = CircuitBreakerState.OPEN
        self._cb_state_changed_at = datetime.now()
        self._cb_failure_count = 0
        self._logger.warning(f"Circuit breaker OPEN (threshold={self._cb_failure_threshold})")

    def _cb_reset_locked(self) -> None:
        self._cb_state = CircuitBreakerState.CLOSED
        self._cb_state_changed_at = datetime.now()
        self._cb_failure_count = 0
        self._logger.info("Circuit breaker CLOSED")

    async def get_circuit_breaker_metrics(self) -> Dict[str, Any]:
        async with self._cb_lock:
            return {
                'state': self._cb_state.value,
                'failure_count': self._cb_failure_count,
                'failure_threshold': self._cb_failure_threshold,
                'state_changed_at': self._cb_state_changed_at.isoformat(),
            }

    def start_loop(self) -> None:
        """
        ✅ FIXED: Now also sets `_running = True` to satisfy `is_healthy` invariant.
        
        قبل از این اصلاح، `start_loop` فقط `_loop_running = True` می‌کرد ولی
        `_running` هم‌چنان False می‌ماند و `is_healthy` هرگز True برنمی‌گشت.
        """
        phase = "CLE_START_LOOP_V4_FIXED"
        try:
            # ─── Idempotency check ──────────────────────────────────────────────
            if self._loop_running and self._task_alive_safe(self._loop_task):
                logger.debug(f"[{phase}] ℹ️ Learning loop already running - skipping")
                return

            # ═══════════════════════════════════════════════════════════════════
            # ✅ FIX: Mark engine as "running" so that `is_healthy` returns True.
            # This is the invariant that was missing.
            # ═══════════════════════════════════════════════════════════════════
            self._running = True

            # ─── Reset retry/degradation state ──────────────────────────────────
            self._loop_retry_count = 0
            self._loop_consecutive_failures = 0
            self._degradation_mode_active = False
            self._degradation_mode_start_time = None
            self._loop_running = True

            # ─── Start learning loop ────────────────────────────────────────────
            self._loop_task = asyncio.create_task(self._learning_loop())

            # ─── Start heartbeat ────────────────────────────────────────────────
            if not hasattr(self, "_heartbeat_task") \
                    or self._heartbeat_task is None \
                    or self._heartbeat_task.done():
                self._heartbeat_task = asyncio.create_task(self._heartbeat_loop())
                logger.info(f"[{phase}] 💓 Heartbeat monitor started.")

            logger.info(
                f"[{phase}] ✅ Learning loop started "
                f"(running={self._running}, loop_running={self._loop_running})"
            )

        except Exception as e:
            logger.error(f"[{phase}] ❌ Start loop error: {e}", exc_info=True)
            self._loop_running = False
            raise

    @staticmethod
    def _task_alive_safe(task: Optional[asyncio.Task]) -> bool:
        """Safely check whether an asyncio task is still alive."""
        try:
            return task is not None and not task.done()
        except Exception:
            return False
        
    async def _heartbeat_loop(self) -> None:
        """
        ✅ NEW V3.0: Independent Heartbeat.
        Updates 'last_success_time' every 60 seconds to prevent Health Check timeouts
        during periods of market inactivity (Idle State).
        """
        phase = "CLE_HEARTBEAT_LOOP"
        try:
            while self._loop_running:
                try:
                    await asyncio.sleep(60) # Beat every 60 seconds
                    if self._loop_running:
                        # ✅ CRITICAL: Update success time to satisfy Health Check
                        self._loop_last_success_time = datetime.now()
                        # Optional: Reset consecutive failures if we are alive
                        if self._loop_consecutive_failures > 0:
                             self._loop_consecutive_failures = 0
                except asyncio.CancelledError:
                    break
                except Exception as hb_err:
                    logger.warning(f"[{phase}] ⚠️ Heartbeat error: {hb_err}")
                    await asyncio.sleep(10)
        except Exception as e:
            logger.error(f"[{phase}] ❌ Heartbeat loop crashed: {e}", exc_info=True)
            
    async def _generate_periodic_report(self) -> None:
        """تولید گزارش دوره‌ای از وضعیت CLE."""
        phase = "PERIODIC_REPORT"
        try:
            repo_metrics = await self._repo_get_metrics()
            cb_metrics = await self.get_circuit_breaker_metrics()

            report = {
                "timestamp": datetime.now().isoformat(),
                "repository": repo_metrics,
                "circuit_breaker": cb_metrics,
                "stats": getattr(self, "_stats", {}),
                "loop_running": self._loop_running,
            }

            self._logger.debug(f"[{phase}] {json.dumps(report, default=str)}")

            # ─── ارسال به تلگرام (sync، بدون await) ─────────────────────
            try:
                message = (
                    f"🧠 *CLE Periodic Report*\n"
                    f"   Processed: {repo_metrics.get('processed', 0)}\n"
                    f"   Pending: {repo_metrics.get('pending', 0)}\n"
                    f"   CB State: {cb_metrics.get('state', 'UNKNOWN')}\n"
                    f"   Time: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}"
                )
                # ✅ FIX: tel_log.trade یک متد sync است و return value آن None است.
                # await روی آن TypeError می‌دهد.
                tel_log.trade(message)
            except Exception as tel_err:
                self._logger.debug(f"[{phase}] Telegram report error: {tel_err}")

        except Exception as e:
            self._logger.warning(f"[{phase}] Error: {e}")
        
    async def _update_strategy_weights(self) -> None:
        """
        ╔══════════════════════════════════════════════════════════════════════════════╗
        ║         UPDATE STRATEGY WEIGHTS - V2.0 (FULL IMPLEMENTATION)               ║
        ║                      ✅ COMPLETE IMPLEMENTATION                            ║
        ║                      ✅ MDE INTEGRATION                                    ║
        ║                      ✅ PERFORMANCE TRACKING                               ║
        ║                      ✅ COMPLETE LOGGING                                   ║
        ║                      ✅ ERROR HANDLING                                     ║
        ║                      ✅ FIXED: Changed warning to debug for no data        ║
        ╚══════════════════════════════════════════════════════════════════════════════╝
        به‌روزرسانی وزن استراتژی‌ها بر اساس عملکرد اخیر.
        مراحل:
        1. بررسی MDE
        2. جمع‌آوری عملکرد استراتژی‌ها
        3. محاسبه وزن‌های جدید
        4. به‌روزرسانی MDE
        5. ذخیره نتایج
        """
        phase = "UPDATE_STRATEGY_WEIGHTS_V2"
        start_time = time.time()
        try:
            # ─── PHASE 1: CHECK MDE ──────────────────────────────────────────────
            self.logger.info(f"[{phase}] 📍 [1/5] Checking MDE availability...")
            if not hasattr(self, '_mde') or self._mde is None:
                self.logger.warning(f"[{phase}] ⚠️ MDE not available - skipping weight update")
                self._stats['weight_updates_skipped_no_mde'] = self._stats.get('weight_updates_skipped_no_mde', 0) + 1
                return
            if not hasattr(self._mde, 'get_weights') or not hasattr(self._mde, 'set_weights'):
                self.logger.warning(f"[{phase}] ⚠️ MDE does not support get_weights/set_weights - skipping")
                self._stats['weight_updates_skipped_mde_incompatible'] = self._stats.get('weight_updates_skipped_mde_incompatible', 0) + 1
                return
            self.logger.info(f"[{phase}] ✅ MDE check passed")
            # ─── PHASE 2: GET CURRENT WEIGHTS ────────────────────────────────────
            self.logger.info(f"[{phase}] 📍 [2/5] Getting current weights...")
            try:
                current_weights = self._mde.get_weights()
                if not current_weights:
                    self.logger.warning(f"[{phase}] ⚠️ No current weights found")
                    return
                self.logger.info(f"[{phase}] ✅ Found {len(current_weights)} strategies with weights")
                # لاگ وزن‌های فعلی
                for strategy_name, weight in list(current_weights.items())[:5]:
                    self.logger.debug(f"[{phase}]    {strategy_name}: {weight:.3f}")
                if len(current_weights) > 5:
                    self.logger.debug(f"[{phase}]    ... and {len(current_weights) - 5} more")
            except Exception as weights_err:
                self.logger.error(f"[{phase}] ❌ Error getting current weights: {weights_err}", exc_info=True)
                return
            
            # ─── PHASE 3: COLLECT STRATEGY PERFORMANCE ───────────────────────────
            self.logger.info(f"[{phase}] 📍 [3/5] Collecting strategy performance...")
            strategy_performance = {}
            try:
                # ✅ FIX P0 (SSOT): ابتدا از strategy_performance (DB-backed)
                # سپس fallback به strategy_metadata (فقط برای فیلدهای تکمیلی)
                if hasattr(self, '_signal_file_manager') and self._signal_file_manager:
                    try:
                        # ─── مسیر ترجیحی: strategy_performance (DB-fresh) ──
                        if hasattr(self._signal_file_manager, 'strategy_performance'):
                            perf_view = self._signal_file_manager.strategy_performance
                            if isinstance(perf_view, dict):
                                for strategy_name, perf in perf_view.items():
                                    if not isinstance(perf, dict):
                                        continue
                                    if not perf.get("exists"):
                                        continue
                                    strategy_performance[strategy_name] = {
                                        'win_rate': float(perf.get('win_rate', 0.5) or 0.5),
                                        'total_trades': int(perf.get('total_trades', 0) or 0),
                                        'winning_trades': int(perf.get('winning_trades', 0) or 0),
                                        'losing_trades': int(perf.get('losing_trades', 0) or 0),
                                        'total_pnl': float(perf.get('total_pnl', 0.0) or 0.0),
                                        'avg_pnl': float(perf.get('avg_pnl', 0.0) or 0.0),
                                        'consecutive_losses': int(perf.get('consecutive_losses', 0) or 0),
                                        'consecutive_wins': int(perf.get('consecutive_wins', 0) or 0),
                                        'penalty': float(perf.get('penalty', 0.0) or 0.0),
                                        'is_blocked': bool(perf.get('is_blocked', False)),
                                        '_source': perf.get('counters_source', 'pm_ssot'),
                                    }

                        # ─── fallback: metadata برای فیلدهای تکمیلی ─────────
                        if hasattr(self._signal_file_manager, 'strategy_metadata'):
                            metadata = self._signal_file_manager.strategy_metadata
                            if isinstance(metadata, dict):
                                for strategy_name, meta in metadata.items():
                                    if not isinstance(meta, dict):
                                        continue
                                    if strategy_name in strategy_performance:
                                        continue  # SSOT داریم
                                    strategy_performance[strategy_name] = {
                                        'win_rate': float(meta.get('win_rate', 0.5) or 0.5),
                                        'total_trades': int(meta.get('total_trades', 0) or 0),
                                        'winning_trades': int(meta.get('winning_trades', 0) or 0),
                                        'losing_trades': int(meta.get('losing_trades', 0) or 0),
                                        'total_pnl': float(meta.get('total_pnl', 0.0) or 0.0),
                                        'avg_pnl': float(meta.get('avg_pnl', 0.0) or 0.0),
                                        'consecutive_losses': int(meta.get('consecutive_losses', 0) or 0),
                                        'consecutive_wins': int(meta.get('consecutive_wins', 0) or 0),
                                        'penalty': float(meta.get('penalty', 0.0) or 0.0),
                                        'is_blocked': bool(meta.get('is_blocked', False)),
                                        '_source': 'metadata_fallback',
                                    }

                        self.logger.info(
                            f"[{phase}] ✅ Collected performance for "
                            f"{len(strategy_performance)} strategies "
                            f"(SSOT: strategy_performance)"
                        )
                    except Exception as sfm_err:
                        self.logger.warning(f"[{phase}] ⚠️ Could not collect from SFM: {sfm_err}")

                # engine fallback (بدون تغییر)
                if hasattr(self, '_engine') and self._engine:
                    try:
                        if hasattr(self._engine, 'strategy_performance'):
                            engine_perf = self._engine.strategy_performance
                            for strategy_name, perf in engine_perf.items():
                                if strategy_name not in strategy_performance and isinstance(perf, dict):
                                    strategy_performance[strategy_name] = perf
                                    self.logger.debug(f"[{phase}]    Added {strategy_name} from engine")
                    except Exception as engine_err:
                        self.logger.warning(f"[{phase}] ⚠️ Could not collect from engine: {engine_err}")
            except Exception as collect_err:
                self.logger.error(f"[{phase}] ❌ Error collecting performance: {collect_err}", exc_info=True)
            # ─── PHASE 4: CALCULATE NEW WEIGHTS ──────────────────────────────────
            self.logger.info(f"[{phase}] 📍 [4/5] Calculating new weights...")
            new_weights = {}
            weight_changes = []
            try:
                for strategy_name, current_weight in current_weights.items():
                    try:
                        # دریافت عملکرد استراتژی
                        perf = strategy_performance.get(strategy_name, {})
                        # استخراج متریک‌ها
                        win_rate = perf.get('win_rate', 0.5)
                        total_trades = perf.get('total_trades', 0)
                        consecutive_losses = perf.get('consecutive_losses', 0)
                        penalty = perf.get('penalty', 0.0)
                        is_blocked = perf.get('is_blocked', False)
                        # محاسبه وزن جدید بر اساس عملکرد
                        new_weight = current_weight
                        # ─── قانون ۱: استراتژی مسدود شده ────────────────────────
                        if is_blocked:
                            new_weight = max(0.05, current_weight * 0.5)
                            self.logger.debug(f"[{phase}]    {strategy_name}: BLOCKED -> {new_weight:.3f}")
                        # ─── قانون ۲: ضررهای متوالی ─────────────────────────────
                        elif consecutive_losses >= 5:
                            new_weight = max(0.05, current_weight * 0.7)
                            self.logger.debug(f"[{phase}]    {strategy_name}: 5+ losses -> {new_weight:.3f}")
                        # ─── قانون ۳: win_rate پایین ────────────────────────────
                        elif total_trades >= 10 and win_rate < 0.35:
                            new_weight = max(0.05, current_weight * 0.8)
                            self.logger.debug(f"[{phase}]    {strategy_name}: WR<35% -> {new_weight:.3f}")
                        # ─── قانون ۴: win_rate بالا ─────────────────────────────
                        elif total_trades >= 10 and win_rate > 0.65:
                            new_weight = min(0.50, current_weight * 1.2)
                            self.logger.debug(f"[{phase}]    {strategy_name}: WR>65% -> {new_weight:.3f}")
                        # ─── قانون ۵: پنالتی بالا ───────────────────────────────
                        elif penalty > 0.5:
                            new_weight = max(0.05, current_weight * (1.0 - penalty * 0.5))
                            self.logger.debug(f"[{phase}]    {strategy_name}: penalty={penalty:.2f} -> {new_weight:.3f}")
                        # ─── قانون ۶: عملکرد خوب ────────────────────────────────
                        elif total_trades >= 5 and win_rate > 0.55:
                            new_weight = min(0.50, current_weight * 1.1)
                            self.logger.debug(f"[{phase}]    {strategy_name}: good performance -> {new_weight:.3f}")
                        # ─── قانون ۷: داده ناکافی ───────────────────────────────
                        elif total_trades < 5:
                            # حفظ وزن فعلی
                            new_weight = current_weight
                            self.logger.debug(f"[{phase}]    {strategy_name}: insufficient data -> {new_weight:.3f}")
                        # بررسی تغییر
                        if abs(new_weight - current_weight) > 0.001:
                            weight_changes.append({
                                'strategy': strategy_name,
                                'old_weight': current_weight,
                                'new_weight': new_weight,
                                'change': new_weight - current_weight
                            })
                        new_weights[strategy_name] = new_weight
                    except Exception as calc_err:
                        self.logger.warning(f"[{phase}] ⚠️ Error calculating weight for {strategy_name}: {calc_err}")
                        # حفظ وزن فعلی در صورت خطا
                        new_weights[strategy_name] = current_weight
                # ─── نرمال‌سازی وزن‌ها ────────────────────────────────────────────
                total_weight = sum(new_weights.values())
                if total_weight > 0:
                    # نرمال‌سازی به مجموع 1.0
                    new_weights = {k: v / total_weight for k, v in new_weights.items()}
                    self.logger.debug(f"[{phase}] ✅ Weights normalized to sum=1.0")
                else:
                    self.logger.warning(f"[{phase}] ⚠️ Total weight is 0, keeping current weights")
                    new_weights = current_weights
            except Exception as calc_err:
                self.logger.error(f"[{phase}] ❌ Error calculating weights: {calc_err}", exc_info=True)
                return
            # ─── PHASE 5: UPDATE MDE ─────────────────────────────────────────────
            self.logger.info(f"[{phase}] 📍 [5/5] Updating MDE with new weights...")
            try:
                self._mde.set_weights(new_weights)
                self.logger.info(f"[{phase}] ✅ MDE updated successfully")
                # لاگ تغییرات وزن
                if weight_changes:
                    self.logger.info(f"[{phase}] 📊 Weight changes ({len(weight_changes)}):")
                    for change in weight_changes[:10]:
                        direction = "↑" if change['change'] > 0 else "↓"
                        self.logger.info(
                            f"[{phase}]    {change['strategy']}: "
                            f"{change['old_weight']:.3f} → {change['new_weight']:.3f} "
                            f"({direction}{abs(change['change']):.3f})"
                        )
                    if len(weight_changes) > 10:
                        self.logger.info(f"[{phase}]    ... and {len(weight_changes) - 10} more changes")
                # به‌روزرسانی آمار
                self._stats['weight_updates'] = self._stats.get('weight_updates', 0) + 1
                self._stats['last_weight_update'] = datetime.now().isoformat()
                self._stats['weight_changes_count'] = len(weight_changes)
            except Exception as update_err:
                self.logger.error(f"[{phase}] ❌ Error updating MDE: {update_err}", exc_info=True)
                return
            # ─── FINAL LOGGING ───────────────────────────────────────────────────
            elapsed_ms = (time.time() - start_time) * 1000
            self.logger.info(f"[{phase}] ═══════════════════════════════════════════════════════════════")
            self.logger.info(f"[{phase}] ✅ WEIGHT UPDATE COMPLETE")
            self.logger.info(f"[{phase}]    Strategies: {len(new_weights)}")
            self.logger.info(f"[{phase}]    Changes: {len(weight_changes)}")
            self.logger.info(f"[{phase}]    Elapsed: {elapsed_ms:.1f}ms")
            self.logger.info(f"[{phase}] ═══════════════════════════════════════════════════════════════")
        except Exception as e:
            self.logger.error(f"[{phase}] ❌ CRITICAL ERROR: {e}", exc_info=True)
            # به‌روزرسانی آمار خطا
            self._stats['weight_update_errors'] = self._stats.get('weight_update_errors', 0) + 1
            self._stats['last_weight_error'] = str(e)
            self._stats['last_weight_error_time'] = datetime.now().isoformat()
            
    async def stop_loop(self, timeout_seconds: int = 60) -> None:
        """توقف امن حلقه پردازش دسته‌ای با drain کارهای در جریان."""
        if not self._loop_running:
            return

        self._logger.info("CLE loop: starting graceful shutdown")
        self._loop_running = False
        self._shutdown_event.set()

        try:
            await asyncio.wait_for(self._drain_complete.wait(), timeout=timeout_seconds)
            self._logger.info("CLE loop: drain completed")
        except asyncio.TimeoutError:
            self._logger.warning("CLE loop: drain timeout - forcing shutdown")

        for task in self._processing_tasks:
            if not task.done():
                task.cancel()

        for t in (self._loop_task, self._health_check_task):
            if t and not t.done():
                t.cancel()
                try:
                    await t
                except asyncio.CancelledError:
                    pass

        self._logger.info("CLE loop: shutdown complete")

    async def _run_loop(self) -> None:
        while self._loop_running:
            try:
                await self._process_batch()
                await self._update_loop_metrics()
                await self._maybe_send_report()
                await asyncio.sleep(self._interval_seconds)
            except asyncio.CancelledError:
                self._logger.info("CLE loop: cancelled")
                break
            except Exception as e:
                self._logger.error(f"CLE loop: fatal error: {e}", exc_info=True)
                await asyncio.sleep(min(self._interval_seconds * 2, 300))

        self._drain_complete.set()

    async def _run_health_check(self) -> None:
        while self._loop_running:
            try:
                await asyncio.sleep(60)
                repo_metrics = await self._repo_get_metrics()
                cb_metrics = await self.get_circuit_breaker_metrics()

                stuck_duration = 300
                if self._loop_metrics.last_processed_timestamp:
                    idle = datetime.now() - self._loop_metrics.last_processed_timestamp
                    if idle > timedelta(seconds=stuck_duration) and repo_metrics['pending'] > 0:
                        self._logger.warning(
                            f"CLE health check: no processing for {stuck_duration}s "
                            f"with {repo_metrics['pending']} pending trades"
                        )

                self._logger.debug(
                    f"CLE health: repo={repo_metrics}, cb={cb_metrics['state']}, "
                    f"processed={self._loop_metrics.total_processed}"
                )
            except asyncio.CancelledError:
                break
            except Exception as e:
                self._logger.error(f"Health check error: {e}")

    async def _process_batch(self) -> Dict[str, int]:
        """
        یک Batch از معاملات را پردازش کرده و موفقیت واقعی Taskها را می‌شمارد.

        Returns:
            دیکشنری آمار processed، succeeded، failed و timed_out.
        """
        stats = {
            "processed": 0,
            "succeeded": 0,
            "failed": 0,
            "timed_out": 0,
        }

        if not await self._cb_can_execute():
            self._logger.warning(
                "Circuit breaker is OPEN; batch processing skipped"
            )
            return stats

        pending_trades = await self._repo_get_pending(
            limit=self._max_batch_size
        )

        if not pending_trades:
            self._logger.debug("No pending trades to process")
            return stats

        tasks: List[asyncio.Task] = []

        for trade in pending_trades:
            task = asyncio.create_task(
                self._process_trade_with_retry(trade)
            )
            tasks.append(task)
            self._processing_tasks.add(task)

        try:
            done, pending = await asyncio.wait(
                tasks,
                timeout=self._processing_timeout_seconds,
                return_when=asyncio.ALL_COMPLETED,
            )

            for task in pending:
                task.cancel()
                stats["timed_out"] += 1

            if pending:
                await asyncio.gather(
                    *pending,
                    return_exceptions=True,
                )

            for task in done:
                stats["processed"] += 1

                if task.cancelled():
                    stats["failed"] += 1
                    continue

                exception = task.exception()
                if exception is not None:
                    stats["failed"] += 1
                    self._logger.error(
                        "CLE task failed with unhandled exception",
                        exc_info=(
                            type(exception),
                            exception,
                            exception.__traceback__,
                        ),
                    )
                    continue

                result = task.result()
                if isinstance(result, dict) and result.get("success") is True:
                    stats["succeeded"] += 1
                else:
                    stats["failed"] += 1

            self._stats["batch_processed"] = (
                self._stats.get("batch_processed", 0) + 1
            )
            self._stats["total_processed_batch"] = (
                self._stats.get("total_processed_batch", 0)
                + stats["processed"]
            )
            self._stats["total_success_batch"] = (
                self._stats.get("total_success_batch", 0)
                + stats["succeeded"]
            )
            self._stats["total_errors_batch"] = (
                self._stats.get("total_errors_batch", 0)
                + stats["failed"]
            )
            self._stats["total_skipped_batch"] = (
                self._stats.get("total_skipped_batch", 0)
                + stats["timed_out"]
            )

            denominator = stats["succeeded"] + stats["failed"]
            self._stats["last_batch_success_rate"] = (
                stats["succeeded"] / denominator
                if denominator > 0
                else 0.0
            )

            return stats

        finally:
            for task in tasks:
                self._processing_tasks.discard(task)
                

    async def _process_pending_trades(self) -> None:
        """
        ╔══════════════════════════════════════════════════════════════════╗
        ║  PROCESS PENDING TRADES — V5.0 (FIXED: Process ALL outcomes)    ║
        ║  ✅ FIXED: Now processes ALL closed trades, not just recent     ║
        ║  ✅ FIXED: Better logging to show what's being processed        ║
        ║  ✅ FIXED: Fallback to scan ALL signal files if needed          ║
        ╚══════════════════════════════════════════════════════════════════╝
        """
        phase = "PROCESS_PENDING_TRADES_V5_ALL_OUTCOMES"
        start_time = time.time()
        try:
            # ─── PHASE 1: Circuit breaker ────────────────────────────────
            self.logger.info(f"[{phase}] 📍 [1/6] Checking circuit breaker...")
            if not await self._cb_can_execute():
                self.logger.warning(f"[{phase}] ⚠️ Circuit Breaker is OPEN — skipping")
                return
            
            # ─── PHASE 2: Collect ALL closed trades ──────────────────────
            self.logger.info(f"[{phase}] 📍 [2/6] Collecting ALL closed trades...")
            candidates: List[Dict[str, Any]] = []
            seen_ids: Set[str] = set()
            
            # ─── Source 1: SignalFileManager (primary) ───────────────────
            if hasattr(self, "_signal_file_manager") and self._signal_file_manager is not None:
                sfm = self._signal_file_manager
                if hasattr(sfm, "get_closed_signals"):
                    try:
                        # ✅ FIXED: Increase limit from 100 to 500
                        closed = await sfm.get_closed_signals(limit=500)
                        self.logger.info(f"[{phase}] 📊 SFM returned {len(closed or [])} closed signals")
                        for tr in closed or []:
                            tid = str(tr.get("trade_id") or tr.get("signal_id") or "")
                            if tid and tid not in seen_ids:
                                seen_ids.add(tid)
                                tr["trade_id"] = tid
                                candidates.append(tr)
                    except Exception as sfm_err:
                        self.logger.warning(f"[{phase}] SFM closed-signals error: {sfm_err}")
            
            # ─── Source 2: Direct scan of ALL TP/SL directories ─────────
            if hasattr(self, "_signal_file_manager") and self._signal_file_manager is not None:
                sfm = self._signal_file_manager
                for sub in ("TP", "SL", "CLOSED"):
                    base = getattr(sfm, "signals_dir", None)
                    if base is None:
                        continue
                    sub_dir = Path(base) / sub
                    if not sub_dir.exists():
                        continue
                    # ✅ FIXED: Scan ALL files, not just first 200
                    all_files = list(sub_dir.glob("*.json"))
                    self.logger.info(f"[{phase}] 📂 Found {len(all_files)} files in {sub}")
                    for fp in all_files:
                        try:
                            if fp.stat().st_size == 0:
                                continue
                            with open(fp, "r", encoding="utf-8") as f:
                                data = json.load(f)
                            status = str(data.get("status", "")).upper()
                            if status not in {"CLOSED", "FILLED"}:
                                continue
                            tid = str(data.get("trade_id") or data.get("signal_id") or fp.stem)
                            if not tid or tid in seen_ids:
                                continue
                            seen_ids.add(tid)
                            data["trade_id"] = tid
                            data["file_path"] = str(fp)
                            data["source"] = f"DirectScan:{sub}"
                            candidates.append(data)
                        except Exception:
                            continue
            
            # ─── Source 3: Engine.closed_trades (if present) ─────────────
            engine = getattr(self, "_engine", None)
            if engine is not None:
                for attr in ("closed_trades", "trade_history"):
                    history = getattr(engine, attr, None)
                    if not isinstance(history, list):
                        continue
                    # ✅ FIXED: Scan ALL history, not just last 200
                    for tr in history:
                        if not isinstance(tr, dict):
                            continue
                        status = str(tr.get("status", "")).upper()
                        if status not in {"CLOSED", "FILLED"}:
                            continue
                        tid = str(tr.get("trade_id") or tr.get("id") or tr.get("signal_id") or "")
                        if tid and tid not in seen_ids:
                            seen_ids.add(tid)
                            candidates.append(tr)
            
            self.logger.info(f"[{phase}] ✅ Total candidates collected: {len(candidates)}")
            
            # ─── PHASE 3: Filter already-processed ───────────────────────
            self.logger.info(f"[{phase}] 📍 [3/6] Filtering already-processed trades...")
            to_process: List[Dict[str, Any]] = []
            already_processed = 0
            
            for tr in candidates:
                tid = str(tr.get("trade_id") or "")
                if not tid:
                    continue
                try:
                    if await self._is_trade_processed_db(tid):
                        already_processed += 1
                        continue
                except Exception as proc_err:
                    self.logger.debug(f"[{phase}] is_processed check failed for {tid}: {proc_err}")
                to_process.append(tr)
            
            self.logger.info(f"[{phase}] 📊 Already processed: {already_processed}, To process: {len(to_process)}")
            
            if not to_process:
                self.logger.info(f"[{phase}] ℹ️ No new CLOSED trades to process")
                await self._cb_record_success()
                return
            
            # ─── PHASE 4: Process in chunks ──────────────────────────────
            self.logger.info(f"[{phase}] 📍 [4/6] Processing {len(to_process)} trades...")
            processed = success = failed = skipped = 0
            chunk_size = 20  # ✅ FIXED: Increased from 10 to 20
            
            for i in range(0, len(to_process), chunk_size):
                chunk = to_process[i : i + chunk_size]
                self.logger.info(f"[{phase}] 🔄 Processing chunk {i//chunk_size + 1}: {len(chunk)} trades")
                
                tasks = [
                    asyncio.create_task(self._process_trade_with_retry(tr))
                    for tr in chunk
                ]
                try:
                    done, pending = await asyncio.wait(
                        tasks,
                        timeout=self._processing_timeout_seconds,
                        return_when=asyncio.ALL_COMPLETED,
                    )
                    for t in pending:
                        t.cancel()
                        skipped += 1
                    for t in done:
                        processed += 1
                        try:
                            res = t.result()
                            if isinstance(res, dict) and res.get("success"):
                                success += 1
                            else:
                                failed += 1
                                self.logger.warning(f"[{phase}] ❌ Trade failed: {res.get('error', 'Unknown')}")
                        except Exception:
                            failed += 1
                except Exception as batch_err:
                    self.logger.error(f"[{phase}] ❌ Batch error: {batch_err}", exc_info=True)
                    failed += len(chunk)
                finally:
                    for t in tasks:
                        if not t.done():
                            t.cancel()
            
            # ─── PHASE 5: Final logging ──────────────────────────────────
            elapsed_ms = (time.time() - start_time) * 1000.0
            self.logger.info(f"[{phase}] ═══════════════════════════════════════════════════")
            self.logger.info(f"[{phase}] ✅ BATCH COMPLETE")
            self.logger.info(f"[{phase}]    Processed: {processed}")
            self.logger.info(f"[{phase}]    Success: {success}")
            self.logger.info(f"[{phase}]    Failed: {failed}")
            self.logger.info(f"[{phase}]    Skipped: {skipped}")
            self.logger.info(f"[{phase}]    Elapsed: {elapsed_ms:.0f}ms")
            self.logger.info(f"[{phase}] ═══════════════════════════════════════════════════")
            
            if failed == 0 and success > 0:
                await self._cb_record_success()
                
        except Exception as e:
            self.logger.error(f"[{phase}] ❌ CRITICAL ERROR: {e}", exc_info=True)
        
    async def add_trade(
        self,
        trade_data: Dict[str, Any],
    ) -> Optional[str]:
        """
        یک معامله بسته‌شده را به Repository اصلی CLE اضافه می‌کند.

        Returns:
            شناسه معامله یا None در صورت نامعتبر بودن ورودی.
        """
        phase = "CLE_ADD_TRADE"

        if not isinstance(trade_data, dict):
            self._logger.error(
                "[%s] trade_data must be a dictionary",
                phase,
            )
            return None

        trade = dict(trade_data)

        trade_id = str(
            trade.get("trade_id")
            or trade.get("id")
            or trade.get("signal_id")
            or uuid.uuid4()
        )

        trade["id"] = trade_id
        trade["trade_id"] = trade_id

        if await self._is_trade_processed_db(trade_id):
            self._logger.debug(
                "[%s] Trade %s was already processed",
                phase,
                trade_id,
            )
            return trade_id

        normalized = self._validate_and_normalize_trade(trade)
        if normalized is None:
            self._logger.warning(
                "[%s] Trade %s failed validation",
                phase,
                trade_id,
            )
            return None

        repository_trade = dict(trade)
        repository_trade["id"] = trade_id
        repository_trade["trade_id"] = trade_id
        repository_trade["symbol"] = normalized["symbol"]
        repository_trade["pnl"] = normalized["pnl"]
        repository_trade["status"] = "CLOSED"
        repository_trade["strategies_used"] = normalized[
            "strategies_used"
        ]
        repository_trade["regime"] = normalized["regime"]
        repository_trade["position_id"] = normalized["position_id"]

        await self._repo_add(repository_trade)

        self._logger.info(
            "[%s] Trade %s added to CLE repository",
            phase,
            trade_id,
        )
        return trade_id
        
    async def _send_telegram_achievement_report(self, achievements: Dict[str, Any]) -> None:
        """
        ✅ NEW: Send achievement report to Telegram
        """
        try:

            success_rate = (
                self._loop_metrics.total_processed / 
                max(1, self._loop_metrics.total_processed + self._loop_metrics.total_failed)
            )
            
            message = (
                "🧠 *CLE Achievement Report*\n"
                f"   ✅ Processed: {self._loop_metrics.total_processed}\n"
                f"   ❌ Failed: {self._loop_metrics.total_failed}\n"
                f"   ⏭️  Skipped: {self._loop_metrics.total_skipped}\n"
                f"   📊 Success Rate: {success_rate:.1%}\n"
                f"   ⏱️  Avg Latency: {self._loop_metrics.processing_latency_avg_ms:.1f}ms\n"
                f"   🔄 Circuit Breaker: {self._cb_state.value}\n"
                f"   📈 Queue Depth: {self._loop_metrics.queue_depth}\n"
                f"   🏆 Status: {'🟢 HEALTHY' if success_rate > 0.8 else '🟡 WARNING' if success_rate > 0.5 else '🔴 CRITICAL'}\n"
                f"   ⏰ Time: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}"
            )
            
            tel_log.trade(message)
            
            logger.debug("✅ Achievement report sent to Telegram")
            
        except Exception as e:
            logger.warning(f"Could not send Telegram achievement report: {e}")
            
    async def _update_loop_metrics(self) -> None:
        """(رفع باگ V7: قبلاً no-op بود) queue_depth و cb_state را زنده می‌کند."""
        repo_metrics = await self._repo_get_metrics()
        self._loop_metrics.queue_depth = repo_metrics['pending']
        self._loop_metrics.circuit_breaker_state = self._cb_state.value

    async def _maybe_send_report(self) -> None:
        now = time.time()
        if now - self._last_report_time < self._report_interval_seconds:
            return
        self._last_report_time = now

        try:
            cle_report = await self.generate_report()
            if cle_report:
                await self._send_telegram_report(cle_report)

            repo_metrics = await self._repo_get_metrics()
            cb_metrics = await self.get_circuit_breaker_metrics()

            self._logger.info(
                f"CLE Report: processed={self._loop_metrics.total_processed}, "
                f"failed={self._loop_metrics.total_failed}, "
                f"skipped={self._loop_metrics.total_skipped}, "
                f"pending={repo_metrics['pending']}, "
                f"cb_state={cb_metrics['state']}"
            )
        except Exception as e:
            self._logger.error(f"Failed to send report: {e}")

    async def _send_telegram_report(self, cle_report: Dict[str, Any]) -> None:
        try:
            summary = cle_report.get('summary', {})
            cb_state = cle_report.get('loop_status', {}).get('circuit_breaker_state', self._cb_state.value)

            message = (
                "🧠 *CLE Report*\n"
                f"   Processed: {self._loop_metrics.total_processed}\n"
                f"   Failed: {self._loop_metrics.total_failed}\n"
                f"   Skipped: {self._loop_metrics.total_skipped}\n"
                f"   Total Strategies: {summary.get('total_strategies', 0)}\n"
                f"   Total PnL: ${summary.get('total_pnl', 0):.2f}\n"
                f"   CB State: {cb_state}\n"
                f"   Time: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}"
            )

            tel_log.trade(message)
            self._logger.debug("CLE report sent via Telegram")
        except Exception as e:
            self._logger.warning(f"Could not send Telegram report: {e}")

    # ========================================================================
    # SECTION 10: Observability یکپارچه (اصلاح‌شده، بدون ریسک deadlock/کرش)
    # ========================================================================

    async def get_metrics(self) -> Dict[str, Any]:
        """
        نسخه اصلاح‌شده: کاملاً async — دیگر از
        asyncio.run_coroutine_threadsafe(...).result(timeout=1) استفاده
        نمی‌کند (که در نسخه قبلی هنگام فراخوانی از داخل همان event loop
        می‌توانست باعث بلاک‌شدن/کرش شود).
        """
        repo_metrics = await self._repo_get_metrics()
        cb_metrics = await self.get_circuit_breaker_metrics()

        return {
            'processing': {
                'total_processed': self._loop_metrics.total_processed,
                'total_failed': self._loop_metrics.total_failed,
                'total_skipped': self._loop_metrics.total_skipped,
                'avg_latency_ms': self._loop_metrics.processing_latency_avg_ms,
                'max_latency_ms': self._loop_metrics.processing_latency_max_ms,
                'queue_depth': repo_metrics['pending'],
                'last_processed': (
                    self._loop_metrics.last_processed_timestamp.isoformat()
                    if self._loop_metrics.last_processed_timestamp else None
                ),
            },
            'circuit_breaker': cb_metrics,
            'repository': repo_metrics,
            'direct_path': {
                'processed_trades_total': self._processed_count,
                'error_count': self._error_count,
            },
        }

    @property
    def is_running(self) -> bool:
        """آیا موتور اصلی initialize شده و فعال است."""
        return self._running

    @property
    def is_loop_running(self) -> bool:
        """آیا حلقه پردازش دسته‌ای پس‌زمینه فعال است."""
        return self._loop_running

    @property
    def is_healthy(self) -> bool:
        """
        ✅ FIXED V3: Robust health check that considers both _running and _loop_running.
        
        منطق:
          1. اگر loop در حال اجراست، engine سالم است (مگر باگ‌های خاص).
          2. اگر loop اجرا نمی‌شود ولی engine initialized است، از نظر health
             نه healthy است و نه کاملاً broken — اما برای CLE maintenance،
             این وضعیت نیاز به recovery دارد.
          3. اگر نه _running و نه _loop_running → unhealthy.
        """
        try:
            # ─── Case A: Loop is running → primary health indicator ─────────────
            if self._loop_running:
                # Sub-checks specific to loop mode
                if getattr(self, "_cb_state", None) == CircuitBreakerState.OPEN:
                    return False
                if getattr(self, "_degradation_mode_active", False):
                    return False
                if getattr(self, "_loop_consecutive_failures", 0) \
                        >= getattr(self, "_loop_max_consecutive_failures", 5):
                    return False
                # Heartbeat freshness check (optional but robust)
                last_success = getattr(self, "_loop_last_success_time", None)
                if last_success is not None:
                    try:
                        age_sec = (datetime.now() - last_success).total_seconds()
                        # اگر بیش از 10 دقیقه هیچ سیگنال سلامتی نداشته‌ایم
                        if age_sec > 600:
                            return False
                    except Exception:
                        pass
                return True

            # ─── Case B: Loop not running → require _running for health ─────────
            return bool(self._running)

        except Exception:
            return False
        
class SignalQualityValidator:
    """
    ╔══════════════════════════════════════════════════════════════════════════════╗
    ║         SIGNAL QUALITY VALIDATOR - INSTITUTIONAL GRADE V1.0                 ║
    ║                                                                              ║
    ║  1. Confluence Score Calculator                                              ║
    ║  2. Signal Freshness Filter                                                  ║
    ║  3. False Signal Memory                                                      ║
    ║  4. Regime-Conditional Signal Weight                                         ║
    ║  5. Bayesian Signal Updater                                                  ║
    ║  6. Multi-Confirmation Gate                                                  ║
    ║  7. Signal Decay Timer                                                       ║
    ╚══════════════════════════════════════════════════════════════════════════════╝
    """

    def __init__(self, max_history: int = 100, decay_seconds: int = 300):
        self.max_history = max_history
        self.decay_seconds = decay_seconds
        self._signal_history: deque = deque(maxlen=max_history)
        self._false_signals: set = set()
        self._confluence_scores: deque = deque(maxlen=max_history)
        logger.info("✅ SignalQualityValidator initialized")

    # ========================================================================
    # 1. CONFLUENCE SCORE CALCULATOR
    # ========================================================================
    def calculate_confluence_score(self, signals: Dict[str, Tuple[str, float]]) -> float:
        """
        signals: dict of {strategy_name: (signal, confidence)}
        """
        score = 0.0
        total_weight = 0.0
        for strategy, (signal, confidence) in signals.items():
            weight = 1.0 if signal in ['BUY', 'SELL'] else 0.5
            score += confidence * weight
            total_weight += weight
        return score / (total_weight + 1e-8)

    def validate_signal(self, signal: str, signals: Dict[str, Tuple[str, float]], regime: str, current_time: datetime, signal_time: datetime) -> Tuple[bool, float, str]:
        try:
            # 1. Freshness Check
            if not self.is_fresh(signal_time, current_time):
                return False, 0.0, "Signal too old"

            # 2. False Signal Memory
            if self.is_false_signal(signal):
                return False, 0.0, "Previously false signal"

            # 3. Multi-Confirmation Gate
            confirmations = [(s, c) for s, c in signals.values() if s in ['BUY', 'SELL', 'STRONG_BUY', 'STRONG_SELL']]
            if not self.multi_confirmation_check(confirmations):
                return False, 0.0, "Insufficient confirmations"

            # 4. Confluence Score
            score = self.calculate_confluence_score(signals)
            if score < 0.3:
                return False, 0.0, f"Low confluence: {score:.2f}"

            # 5. Regime-conditional weight
            weight = self.get_regime_weight(signal, regime)
            if weight < 1.0:
                return True, score * weight, f"Regime weight: {weight:.2f}"

            return True, score, "Valid signal"
        except Exception as e:
            logger.error(f"validate_signal error: {e}")
            return False, 0.0, str(e)
            
    # ========================================================================
    # 2. SIGNAL FRESHNESS FILTER
    # ========================================================================
    def is_fresh(self, signal_time: datetime, current_time: datetime) -> bool:
        return (current_time - signal_time).total_seconds() < self.decay_seconds

    # ========================================================================
    # 3. FALSE SIGNAL MEMORY
    # ========================================================================
    def mark_false_signal(self, signal: str) -> None:
        self._false_signals.add(signal)

    def is_false_signal(self, signal: str) -> bool:
        return signal in self._false_signals

    # ========================================================================
    # 4. REGIME-CONDITIONAL SIGNAL WEIGHT
    # ========================================================================
    def get_regime_weight(self, signal: str, regime: str, oscillator_weight: float = 0.7, trend_weight: float = 1.3) -> float:
        if regime in ['TRENDING', 'STRONG_TRENDING']:
            return trend_weight if signal in ['BUY', 'SELL'] else 1.0
        elif regime in ['RANGING', 'CONSOLIDATION']:
            return oscillator_weight if signal in ['BUY', 'SELL'] else 1.0
        return 1.0

    # ========================================================================
    # 5. BAYESIAN SIGNAL UPDATER
    # ========================================================================
    def bayesian_update(self, prior: float, likelihood: float, confidence: float) -> float:
        posterior = (prior * likelihood) / (prior * likelihood + (1 - prior) * (1 - likelihood))
        return posterior * 0.7 + confidence * 0.3

    # ========================================================================
    # 6. MULTI-CONFIRMATION GATE
    # ========================================================================
    def multi_confirmation_check(self, signals: List[Tuple[str, float]], min_confirmations: int = 3) -> bool:
        buy_count = sum(1 for s, _ in signals if s in ['BUY', 'STRONG_BUY'])
        sell_count = sum(1 for s, _ in signals if s in ['SELL', 'STRONG_SELL'])
        return buy_count >= min_confirmations or sell_count >= min_confirmations

    # ========================================================================
    # 7. SIGNAL DECAY TIMER
    # ========================================================================
    def calculate_decay_multiplier(self, age_seconds: float) -> float:
        if age_seconds >= self.decay_seconds:
            return 0.0
        return 1.0 - (age_seconds / self.decay_seconds)


class DynamicWeightingSystem:
    """
    ╔══════════════════════════════════════════════════════════════════════════════╗
    ║         DYNAMIC WEIGHTING SYSTEM - WALL STREET QUANT EDITION                 ║
    ║                      FULLY INTEGRATED v2.2.0                                 ║
    ║                                                                              ║
    ║  INTEGRATED MODULES:                                                         ║
    ║  ┌─────────────────────────────────────────────────────────────────────────┐║
    ║  │ 1. AdaptiveIndicatorEnsemble    - Gradient Boosting + Dynamic Weights   │║
    ║  │ 2. IndicatorPerformanceTracker  - Accuracy tracking per indicator       │║
    ║  │ 3. AdaptiveLookbackOptimizer    - Regime-based lookback optimization    │║
    ║  └─────────────────────────────────────────────────────────────────────────┘║
    ║                                                                              ║
    ║  FEATURES:                                                                   ║
    ║  ✅ Regime detection (5 regimes with confidence scoring)                    ║
    ║  ✅ Dynamic weight calculation with decay and momentum                      ║
    ║  ✅ Gradient Boosting ensemble (XGBoost fallback)                           ║
    ║  ✅ Lookback optimization per regime                                        ║
    ║  ✅ Persistent caching with auto-save                                       ║
    ║  ✅ Bulletproof error handling                                              ║
    ║  ✅ Comprehensive logging with phase tracking                               ║
    ║  ✅ FIXED V2.2: apply_historical_boost with continuous adjustment          ║
    ╚══════════════════════════════════════════════════════════════════════════════╝
    """
    
    # ========================================================================
    # Market Regime Constants
    # ========================================================================
    REGIME_TRENDING_STRONG = "TRENDING_STRONG"
    REGIME_TRENDING_WEAK = "TRENDING_WEAK"
    REGIME_RANGING = "RANGING"
    REGIME_VOLATILE = "VOLATILE"
    REGIME_BREAKOUT = "BREAKOUT"
    
    # Signal mapping constants
    SIGNAL_MAP = {
        'STRONG_BUY': 1, 'BUY': 1, 'HOLD': 0, 'STRONG_HOLD': 0,
        'SELL': -1, 'STRONG_SELL': -1
    }
    
    REVERSE_SIGNAL_MAP = {
        'STRONG_BUY': 'STRONG_SELL', 'BUY': 'SELL', 'HOLD': 'HOLD',
        'STRONG_HOLD': 'STRONG_HOLD', 'SELL': 'BUY', 'STRONG_SELL': 'STRONG_BUY'
    }

    def __init__(self, 
                 cache_file: str = "TRADE/indicator_performance.json",
                 lookback_days: int = 30,
                 min_samples_for_weight: int = 10,
                 optimization_interval: int = 50,
                 gb_n_estimators: int = 50,
                 gb_learning_rate: float = 0.1,
                 gb_max_depth: int = 3,
                 enable_gradient_boosting: bool = True,
                 weight_decay_rate: float = 0.95,
                 weight_momentum: float = 0.3):
        """
        Initialize the fully integrated Dynamic Weighting System
        
        Args:
            cache_file: Path to cache file for persistence
            lookback_days: Default lookback period for performance tracking
            min_samples_for_weight: Minimum samples before weighting is reliable
            optimization_interval: Frequency of lookback optimization
            gb_n_estimators: Number of Gradient Boosting estimators
            gb_learning_rate: Learning rate for GB model
            gb_max_depth: Max depth of GB trees
            enable_gradient_boosting: Enable GB ensemble learning
            weight_decay_rate: Exponential decay for historical weights
            weight_momentum: Momentum factor for weight updates
        """
        phase = "DYNAMIC_WEIGHTING_INIT"
        
        try:
            # ========== Core Parameters ==========
            self.cache_file = cache_file
            self.lookback_days = lookback_days
            self.min_samples_for_weight = min_samples_for_weight
            self.optimization_interval = optimization_interval
            self.enable_gradient_boosting = enable_gradient_boosting
            self.weight_decay_rate = weight_decay_rate
            self.weight_momentum = weight_momentum
            
            # ========== Performance Tracking Structures ==========
            # Nested structure: symbol -> indicator_name -> IndicatorPerformanceData
            self._performance: Dict[str, Dict[str, IndicatorPerformanceData]] = {}
            self._dynamic_weights: Dict[str, Dict[str, float]] = {}
            self._previous_weights: Dict[str, Dict[str, float]] = {}
            
            # ========== Global Statistics ==========
            self.total_predictions: int = 0
            self.correct_predictions: int = 0
            self._last_save_time: Optional[datetime] = None
            self._save_interval_seconds: int = 60
            
            # ========== Lookback Optimization Structures ==========
            self.lookback_range: Dict[str, Tuple[int, int]] = {
                'RSI': (7, 25), 'MACD_fast': (5, 15), 'MACD_slow': (20, 40),
                'MACD_signal': (5, 15), 'BB_period': (10, 30), 'BB_std': (1.5, 3.0),
                'ADX': (7, 21), 'ATR': (7, 21), 'Stochastic': (7, 21),
                'CCI': (10, 30), 'MFI': (7, 21), 'Volume_SMA': (10, 30),
                'MA_fast': (5, 20), 'MA_slow': (20, 50)
            }
            
            self.default_lookbacks: Dict[str, int] = {
                'RSI': 14, 'MACD_fast': 12, 'MACD_slow': 26, 'MACD_signal': 9,
                'BB_period': 20, 'BB_std': 2, 'ADX': 14, 'ATR': 14,
                'Stochastic': 14, 'CCI': 20, 'MFI': 14, 'Volume_SMA': 20,
                'MA_fast': 9, 'MA_slow': 21
            }
            
            self._optimized_lookbacks: Dict[str, Dict[str, Dict]] = {}
            self._lookback_performance_history: Dict[str, List[Dict]] = {}
            self._optimization_counter: int = 0
            
            # ========== Regime State ==========
            self._current_regime: str = self.REGIME_RANGING
            self._regime_confidence: float = 0.5
            self._last_regime_change: datetime = datetime.now()
            self._regime_change_cooldown_seconds: int = 300
            
            # ========== Gradient Boosting Model ==========
            self._gb_model = None
            self._gb_scaler = None
            self._gb_trained: bool = False
            self._gb_feature_importance: Optional[np.ndarray] = None
            
            if self.enable_gradient_boosting:
                self._init_gradient_boosting(gb_n_estimators, gb_learning_rate, gb_max_depth)
            
            # ========== Indicator Registry ==========
            self._registered_indicators: List[str] = [
                'RSI', 'MACD', 'BB', 'Stochastic', 'CCI', 'MFI', 'ADX',
                'Ichimoku', 'Volume', 'MA_Confluence', 'SuperTrend',
                'Williams_R', 'OBV', 'ATR'
            ]
            
            # Initialize performance tracking for all registered indicators
            self._init_performance_tracking()
            
            # ========== Regime Configurations ==========
            self._regime_configs: Dict[str, RegimeConfig] = self._init_regime_configs()
            
            # ========== Load from Cache ==========
            self._load_from_cache()
            
            # ========== Statistics for Monitoring ==========
            self._stats: Dict[str, Any] = {
                'regime_changes': 0,
                'optimizations_performed': 0,
                'gb_training_epochs': 0,
                'cache_loads': 0,
                'cache_saves': 0,
                'initialization_time': datetime.now().isoformat()
            }
            
            logger.info(f"[{phase}] ✅ DynamicWeightingSystem V2.2 fully initialized")
            logger.info(f"[{phase}]    Cache: {cache_file}")
            logger.info(f"[{phase}]    GB Enabled: {enable_gradient_boosting}")
            logger.info(f"[{phase}]    Min samples: {min_samples_for_weight}")
            logger.info(f"[{phase}]    Registered indicators: {len(self._registered_indicators)}")
            
        except Exception as e:
            logger.error(f"[{phase}] ❌ Initialization failed: {e}", exc_info=True)
            raise

    def _init_gradient_boosting(self, n_estimators: int, learning_rate: float, max_depth: int) -> None:
        """Initialize Gradient Boosting model with fallback options"""
        phase = "GB_INIT"
        
        try:
            # Try XGBoost first (better performance)
            try:
                from xgboost import XGBClassifier
                self._gb_model = XGBClassifier(
                    n_estimators=n_estimators,
                    learning_rate=learning_rate,
                    max_depth=max_depth,
                    random_state=42,
                    verbosity=0,
                    use_label_encoder=False
                )
                logger.info(f"[{phase}] ✅ XGBoost initialized")
            except ImportError:
                # Fallback to sklearn GradientBoostingClassifier
                from sklearn.ensemble import GradientBoostingClassifier
                self._gb_model = GradientBoostingClassifier(
                    n_estimators=n_estimators,
                    learning_rate=learning_rate,
                    max_depth=max_depth,
                    random_state=42
                )
                logger.info(f"[{phase}] ✅ sklearn GradientBoosting initialized")
            
            from sklearn.preprocessing import StandardScaler
            self._gb_scaler = StandardScaler()
            self._gb_trained = False
            
        except Exception as e:
            logger.warning(f"[{phase}] ⚠️ Gradient Boosting unavailable: {e}")
            self.enable_gradient_boosting = False
            self._gb_model = None
    
    def _init_performance_tracking(self) -> None:
        """Initialize performance tracking structures for all indicators"""
        try:
            # Structure will be populated lazily when first used
            # This prevents unnecessary empty entries
            pass
        except Exception as e:
            logger.error(f"Performance tracking init error: {e}")
    
