    total_profit: float
    total_loss: float
    avg_pnl: float
    avg_profit: float
    avg_loss: float
    win_rate: float
    profit_factor: float
    expected_value: float
    sharpe_ratio: float
    sortino_ratio: float
    calmar_ratio: float
